import { requireUser } from "@/lib/auth";
import { db } from "@/lib/db";
import { familyFor } from "@/lib/game-config";
import { StoreBrowser, type SortKey } from "@/components/mods/StoreBrowser";
import { GameCatalogueGrid } from "@/components/mods/GameCatalogueGrid";
import { ModCarouselRow } from "@/components/mods/ModCarouselRow";
import { ModCard } from "@/components/mods/ModCard";
import { PortalRowHeader } from "@/components/mods/PortalRowHeader";
import type { QuickAddServer } from "@/components/mods/QuickAddButton";
import {
  listCatalogFamilies,
  queryCatalogMods,
  listFeaturedMods,
  listTopDownloadedMods,
  listRecentlyUpdatedMods,
  listTopRatedMods,
  totalDownloadsFor,
  formatDownloads,
  type ModSummary,
} from "@/lib/mods-catalog";

export const dynamic = "force-dynamic";

const VALID_SORTS = new Set<SortKey>(["featured", "downloads", "latest", "rating"]);
function parseSort(v?: string): SortKey {
  return v && VALID_SORTS.has(v as SortKey) ? (v as SortKey) : "featured";
}

/**
 * NxLabs, inside the portal — the SAME catalog as the public /mods pages
 * (lib/mods-catalog.ts), with one addition a logged-in customer gets for
 * free: a real, matching server can be added to in one click, right from the
 * grid. Nothing here forks the install path — QuickAddButton calls the same
 * installMod() server action as the per-server Mods tab (ModsPanel.tsx) and
 * the public detail page's AddToServerWidget.
 *
 * Portal/marketing split: this page and everything under app/dashboard/nxlabs/**
 * render through the Nexion portal shell (app/dashboard/layout.tsx ->
 * components/nx/Shell.tsx) automatically by living under /dashboard — the
 * fix for the old bug where a portal mod card linked out to the PUBLIC
 * /mods/[family]/[slug] route is simply that every href below points at this
 * tree's own /dashboard/nxlabs/... routes instead.
 */
type Search = { q?: string; sort?: string; page?: string };

export default async function NxLabsPage({ searchParams }: { searchParams: Promise<Search> }) {
  const user = await requireUser();
  const sp = await searchParams;
  const q = (sp.q ?? "").trim();
  const sort = parseSort(sp.sort);
  const page = Number(sp.page) || 1;

  const [families, result, totalDownloads, myServers, featuredMods, topDownloaded, recentlyUpdated, topRated] = await Promise.all([
    listCatalogFamilies(),
    queryCatalogMods({ q, sort, page }),
    totalDownloadsFor(),
    db.server.findMany({
      where: { userId: user.id, status: { notIn: ["DELETING"] } },
      include: { osTemplate: true, gamePlan: true },
    }),
    listFeaturedMods(undefined, 12),
    listTopDownloadedMods(undefined, 12),
    listRecentlyUpdatedMods(undefined, 12),
    listTopRatedMods(undefined, 12),
  ]);
  const { mods, total, totalPages, perPage, page: resolvedPage } = result;
  const modHref = (m: ModSummary) => `/dashboard/nxlabs/${m.gameFamily}/${m.slug}`;

  // One pass over the (small) server list per mod family, so the grid below
  // does zero extra queries — matches getEligibleServersForMod's own rules
  // (family + variant) but computed once for everyone on the page. Plain
  // object, not a Map — this is handed to a Client Component as a prop and
  // has to be JSON-serializable.
  const serversByFamily: Record<string, QuickAddServer[]> = {};
  for (const s of myServers) {
    const fam = familyFor(s);
    if (!fam) continue;
    (serversByFamily[fam] ??= []).push({ id: s.id, hostname: s.hostname, label: s.label });
  }

  const totalMods = families.reduce((sum, f) => sum + f.count, 0);

  return (
    <div className="mx-auto flex w-full max-w-[1520px] flex-col gap-4">
      {/*
        Bespoke full-bleed header — deliberately NOT PageShell's `heroImage`
        prop. That prop anchors a small `h-[280px] w-auto object-contain`
        illustration to one corner (built for the SSL shield / domains globe
        — a decorative icon beside the text), so wiring it up here just made
        the collage appear as a shrunken corner graphic instead of the full
        card the owner actually asked for: "the hero image needs to take up
        the entire hero card with the text overtop." Left PageShell itself
        untouched since SSL/domains still rely on its real corner-icon
        behavior — this page just doesn't use PageShell for its header.
      */}
      <header className="relative overflow-hidden rounded-[20px] border border-white/[0.06]">
        {/* eslint-disable-next-line @next/next/no-img-element -- static hero art, not an optimizable content image */}
        <img
          src="/nxlabs/hero-collage.png"
          alt=""
          aria-hidden
          className="absolute inset-0 h-full w-full object-cover"
        />
        {/* Scrim so the overlaid text stays readable against whatever part
            of the collage sits behind it, matching the marketing page's own
            full-bleed treatment rather than inventing a different one. */}
        <div
          aria-hidden
          className="absolute inset-0"
          style={{
            background:
              "linear-gradient(180deg, rgba(3,6,16,0.86) 0%, rgba(3,6,16,0.55) 46%, rgba(3,6,16,0.82) 100%)",
          }}
        />
        <div className="relative flex flex-wrap items-start justify-between gap-x-6 gap-y-3 px-6 py-8 sm:px-8 sm:py-10">
          <div className="flex min-w-0 flex-col gap-1">
            <span className="text-[11px] font-extrabold uppercase tracking-[0.22em] text-[#f21cff]">NxLabs</span>
            <h1 className="text-[27px] font-extrabold leading-[1.08] tracking-[-0.032em] text-white sm:text-[31px]">
              Mods &amp; plugins
            </h1>
            <p className="max-w-[62ch] text-[13px] leading-[1.5] text-tx-mute">
              Browse the same verified catalog anyone can — with one-click install for the{" "}
              {myServers.length ? "servers" : "server"} you own.
            </p>
          </div>
          <span className="hidden flex-col items-end gap-[3px] lg:flex">
            {["VERIFIED SOURCES.", "ONE-CLICK INSTALL."].map((l) => (
              <span key={l} className="text-[10px] font-semibold uppercase tracking-[0.28em] text-tx-faint">
                {l}
              </span>
            ))}
          </span>
        </div>
      </header>

      <div className="mb-8 flex flex-wrap items-center gap-6 text-sm text-tx-mute">
        <span>
          <strong className="text-white">{totalMods}</strong> mods &amp; plugins
        </span>
        <span>
          <strong className="text-white">{families.length}</strong> games supported
        </span>
        {totalDownloads > 0 && (
          <span>
            <strong className="text-white">{formatDownloads(totalDownloads)}</strong> total downloads
          </span>
        )}
      </div>

      <div className="mb-10">
        <h2 className="mb-3 text-sm font-semibold uppercase tracking-wide text-tx-mute">Browse by game</h2>
        <GameCatalogueGrid families={families} hrefFor={(family) => `/dashboard/nxlabs/games/${family}`} />
      </div>

      {/* Item 6 of the 2026-09-20 NxLabs overhaul, brought to the portal
          homepage too — same four curated carousel rows as the marketing
          /mods page, real "View more" into the full grid below. */}
      {featuredMods.length > 0 && (
        <div id="featured" className="mb-10">
          <PortalRowHeader title="Featured mods" eyebrow="Editor's picks" viewMoreHref="/dashboard/nxlabs#browse" />
          <div className="mt-4">
            <ModCarouselRow items={featuredMods.map((m) => ({ key: m.id, node: <ModCard mod={m} href={modHref(m)} showGameBadge /> }))} />
          </div>
        </div>
      )}

      {topDownloaded.length > 0 && (
        <div id="top-downloaded" className="mb-10">
          <PortalRowHeader
            title="Most downloaded mods"
            eyebrow="Real downloads, real ranking"
            sub="Ranked by real download counts pulled from each mod's own source."
            viewMoreHref="/dashboard/nxlabs?sort=downloads#browse"
          />
          <div className="mt-4">
            <ModCarouselRow items={topDownloaded.map((m) => ({ key: m.id, node: <ModCard mod={m} href={modHref(m)} showGameBadge /> }))} />
          </div>
        </div>
      )}

      {recentlyUpdated.length > 0 && (
        <div id="recently-updated" className="mb-10">
          <PortalRowHeader
            title="Recently updated mods"
            eyebrow="Straight from the source"
            sub="Real last-shipped timestamps pulled from each mod's own source."
            viewMoreHref="/dashboard/nxlabs?sort=latest#browse"
          />
          <div className="mt-4">
            <ModCarouselRow items={recentlyUpdated.map((m) => ({ key: m.id, node: <ModCard mod={m} href={modHref(m)} showGameBadge /> }))} />
          </div>
        </div>
      )}

      {topRated.length > 0 && (
        <div id="top-rated" className="mb-10">
          <PortalRowHeader
            title="Top rated mods"
            eyebrow="Community favorites"
            sub="Real ratings left by Nxeon customers — approximated by downloads until a mod has enough of its own."
            viewMoreHref="/dashboard/nxlabs?sort=rating#browse"
          />
          <div className="mt-4">
            <ModCarouselRow items={topRated.map((m) => ({ key: m.id, node: <ModCard mod={m} href={modHref(m)} showGameBadge /> }))} />
          </div>
        </div>
      )}

      <div id="browse" className="scroll-mt-6">
        <h2 className="mb-3 text-sm font-semibold uppercase tracking-wide text-tx-mute">Browse everything</h2>
        <StoreBrowser
          mods={mods}
          total={total}
          page={resolvedPage}
          totalPages={totalPages}
          perPage={perPage}
          chips={[]}
          chipField="gameFamily"
          basePath="/dashboard/nxlabs"
          q={q}
          sort={sort}
          showGameBadge
          serversByFamily={serversByFamily}
          deployHref="/dashboard/deploy"
        />
      </div>
    </div>
  );
}

