const VALID_SORTS = new Set<SortKey>(["featured", "downloads", "latest", "rating"]);
function parseSort(v?: string): SortKey {
  return v && VALID_SORTS.has(v as SortKey) ? (v as SortKey) : "featured";
}

type Search = { q?: string; sort?: string; category?: string; page?: string };

/** Portal's own per-game NxLabs page — same data as the marketing one, own chrome/route (item 7). */
export default async function PortalGameModsPage({
  params,
  searchParams,
}: {
  params: Promise<{ family: string }>;
  searchParams: Promise<Search>;
}) {
  const { family } = await params;
  const user = await requireUser();

  const families = await listCatalogFamilies();
  const entry = families.find((f) => f.family === family);
  if (!entry) notFound();

  const sp = await searchParams;
  const q = (sp.q ?? "").trim();
  const sort = parseSort(sp.sort);
  const category = sp.category?.trim() || undefined;
  const page = Number(sp.page) || 1;

  const [categoryCounts, result, totalDownloads, myServers, featuredMods, topDownloaded, recentlyUpdated, topRated] = await Promise.all([
    listCategoryCounts(family),
    queryCatalogMods({ family, category, q, sort, page }),
    totalDownloadsFor(family),
    db.server.findMany({ where: { userId: user.id, status: { notIn: ["DELETING"] } }, include: { osTemplate: true, gamePlan: true } }),
    listFeaturedMods(family),
    listTopDownloadedMods(family),
    listRecentlyUpdatedMods(family),
    listTopRatedMods(family),
  ]);
  const { mods, total, totalPages, perPage, page: resolvedPage } = result;

  const myMatchingServers: QuickAddServer[] = myServers
    .filter((s) => familyFor(s) === family)
    .map((s) => ({ id: s.id, hostname: s.hostname, label: s.label }));

  const label = GAME_DISPLAY[family as GameFamily]?.name ?? entry.label;
  const heroSlug = GAME_ART_SLUG[family as GameFamily]?.hero;
  const modHref = (m: ModSummary) => `/dashboard/nxlabs/${m.gameFamily}/${m.slug}`;

  const chips = categoryCounts.map((c) => ({ key: c.category, label: c.category, count: c.count }));

  return (
    <PageShell
      eyebrow="NxLabs"
      title={`${label} mods & plugins`}
      sub={`${entry.count} verified add-ons for ${label}${totalDownloads > 0 ? ` — ${formatDownloads(totalDownloads)} total downloads` : ""}.`}
      tagline={["VERIFIED SOURCES.", "ONE-CLICK INSTALL."]}
    >
      {/* PageShell's own `heroImage` prop is the wrong tool here: it was built
          for a small, roughly-square decorative illustration (the SSL shield,
          the domains globe — see its own header comment, "wide 900x600 source
          art" as the widest case it was tuned for) rendered `object-contain`
          at a fixed 280-300px height, anchored to the header's right edge.
          Fed one of these wide 16:9 game hero photos instead, that shrinks the
          whole image down to fit the height and letterboxes it into a small
          box pinned to the top-right corner — plain header text filling the
          rest of the row to its left. That is the exact bug this page had.

          A real hero banner needs its own contained section instead — same
          rounded-2xl/object-cover/gradient-scrim treatment already shipped for
          the portal's mod detail page (app/dashboard/nxlabs/[family]/[slug]/
          page.tsx), not a full-bleed viewport edge-to-edge crop like
          marketing's version: the dashboard shell has a fixed content width
          against the sidebar, so "contained" is the correct, different-on-
          purpose portal treatment (see .design-refs/nxlabs/game-page-portal.png
          — a big, prominent banner image, not a decorative corner icon). */}
      {heroSlug && (
        <div className="relative -mt-2 mb-6 min-h-[200px] overflow-hidden rounded-2xl border border-white/10 sm:min-h-[240px]">
          {/* eslint-disable-next-line @next/next/no-img-element */}
          <img
            src={`/games/art/${heroSlug}_hero.jpg`}
            alt=""
            aria-hidden
            className="absolute inset-0 h-full w-full object-cover opacity-60"
          />
          {/* Relightened 2026-09-20 alongside every other NxLabs hero scrim in
              this overhaul (item 2's own comment on the mod detail page has
              the full root-cause writeup) — the old 75%/30% via/to made this
              banner read as a near-solid dark box instead of real game art. */}
          <div className="absolute inset-0 bg-gradient-to-t from-navy-950 via-navy-950/45 to-navy-950/10" />
        </div>
      )}

      {/* Item 6 of the 2026-09-20 NxLabs overhaul: same four curated
          carousel rows as the marketing per-family page, scoped to this
          game. Item 7: showCategoryLabel={false} throughout — the game is
          already the whole page. */}
      {featuredMods.length > 0 && (
        <div id="featured" className="mb-8">
          <PortalRowHeader title={`Featured ${label} mods`} eyebrow="Editor's picks" viewMoreHref={`/dashboard/nxlabs/games/${family}#browse`} />
          <div className="mt-4">
            <ModCarouselRow items={featuredMods.map((m) => ({ key: m.id, node: <ModCard mod={m} href={modHref(m)} showCategoryLabel={false} /> }))} />
          </div>
        </div>
      )}

      {topDownloaded.length > 0 && (
        <div id="top-downloaded" className="mb-8">
          <PortalRowHeader
            title={`Most downloaded ${label} mods`}
            eyebrow="Real downloads, real ranking"
            sub="Ranked by real download counts pulled from each mod's own source."
            viewMoreHref={`/dashboard/nxlabs/games/${family}?sort=downloads#browse`}
          />
          <div className="mt-4">
            <ModCarouselRow items={topDownloaded.map((m) => ({ key: m.id, node: <ModCard mod={m} href={modHref(m)} showCategoryLabel={false} /> }))} />
          </div>
        </div>
      )}

      {recentlyUpdated.length > 0 && (
        <div id="recently-updated" className="mb-8">
          <PortalRowHeader
            title={`Recently updated ${label} mods`}
            eyebrow="Straight from the source"
            sub="Real last-shipped timestamps pulled from each mod's own source."
            viewMoreHref={`/dashboard/nxlabs/games/${family}?sort=latest#browse`}
          />
          <div className="mt-4">
            <ModCarouselRow items={recentlyUpdated.map((m) => ({ key: m.id, node: <ModCard mod={m} href={modHref(m)} showCategoryLabel={false} /> }))} />
          </div>
        </div>
      )}

      {topRated.length > 0 && (
        <div id="top-rated" className="mb-8">
          <PortalRowHeader
            title={`Top rated ${label} mods`}
            eyebrow="Community favorites"
            sub="Real ratings left by Nxeon customers — approximated by downloads until a mod has enough of its own."
            viewMoreHref={`/dashboard/nxlabs/games/${family}?sort=rating#browse`}
          />
          <div className="mt-4">
            <ModCarouselRow items={topRated.map((m) => ({ key: m.id, node: <ModCard mod={m} href={modHref(m)} showCategoryLabel={false} /> }))} />
          </div>
        </div>
      )}

      <div id="browse" className="scroll-mt-6">
        <h2 className="mb-3 text-sm font-semibold uppercase tracking-wide text-tx-mute">Browse all {label} mods</h2>
        <StoreBrowser
          mods={mods}
          total={total}
          page={resolvedPage}
          totalPages={totalPages}
          perPage={perPage}
          chips={chips}
          chipField="category"
          activeChipKey={category}
          basePath="/dashboard/nxlabs"
          browsePath={`/dashboard/nxlabs/games/${family}`}
          q={q}
          sort={sort}
          searchPlaceholder={`Search ${label} mods…`}
          showCategoryLabel={false}
          serversByFamily={{ [family]: myMatchingServers }}
          deployHref="/dashboard/deploy"
        />
      </div>
    </PageShell>
  );
}

