function familyLabel(family: string): string {
  return GAME_DISPLAY[family as GameFamily]?.name ?? family;
}

type RatingAgg = { avg: number | null; count: number };

/** Real average+count per mod, one groupBy query for as many mods as needed at once. */
async function ratingAggs(modIds: string[]): Promise<Map<string, RatingAgg>> {
  if (modIds.length === 0) return new Map();
  const rows = await db.modRating.groupBy({
    by: ["gameModId"],
    where: { gameModId: { in: modIds } },
    _avg: { rating: true },
    _count: { rating: true },
  });
  return new Map(rows.map((r) => [r.gameModId, { avg: r._avg.rating, count: r._count.rating }]));
}

function toSummary(m: GameMod, agg?: RatingAgg): ModSummary {
  return {
    id: m.id,
    gameFamily: m.gameFamily,
    gameFamilyLabel: familyLabel(m.gameFamily),
    name: m.name,
    slug: m.slug,
    category: m.category,
    source: m.source,
    iconUrl: m.iconUrl,
    description: m.description,
    downloads: m.downloads,
    featured: m.featured,
    paid: m.paid,
    verified: m.verifiedAt !== null,
    impact: m.impact,
    createdAt: m.createdAt.toISOString(),
    avgRating: agg?.avg ?? null,
    ratingCount: agg?.count ?? 0,
    url: m.url,
    sourceId: m.sourceId,
    appliesToVariant: m.appliesToVariant,
    upstreamUpdatedAt: m.upstreamUpdatedAt ? m.upstreamUpdatedAt.toISOString() : null,
  };
}

function toDetail(m: GameMod, agg?: RatingAgg): ModDetail {
  return {
    ...toSummary(m, agg),
    url: m.url,
    sourceId: m.sourceId,
    license: m.license,
    gameVersions: m.gameVersions,
    loaders: m.loaders,
    fileBytes: m.fileBytes,
    dependencyCount: m.dependencyCount,
    serverSide: m.serverSide,
    impactNote: m.impactNote,
    appliesToVariant: m.appliesToVariant,
    verifiedAt: m.verifiedAt,
    upstreamOk: m.upstreamOk,
    upstreamNote: m.upstreamNote,
    galleryUrls: m.galleryUrls,
    authorName: m.authorName,
    authorAvatarUrl: m.authorAvatarUrl,
    longDescription: m.longDescription,
  };
}

/** Real, publicly-listable families — active mods with a real upstream today. */
export const listCatalogFamilies = unstable_cache(
  async (): Promise<{ family: string; label: string; count: number }[]> => {
    const rows = await db.gameMod.groupBy({
      by: ["gameFamily"],
      where: { active: true, upstreamOk: true },
      _count: true,
      orderBy: { gameFamily: "asc" },
    });
    return rows
      .map((r) => ({ family: r.gameFamily, label: familyLabel(r.gameFamily), count: r._count }))
      .sort((a, b) => b.count - a.count);
  },
  ["mods-catalog:listCatalogFamilies"],
  { revalidate: CATALOG_AGGREGATE_REVALIDATE_SECONDS }
);

export type CatalogSort = "featured" | "downloads" | "latest" | "rating";

export type CatalogPage = {
  mods: ModSummary[];
  total: number;
  page: number;
  totalPages: number;
  perPage: number;
};

/**
 * Every scalar `orderBy` StoreBrowser's sort tabs can ask for. "rating" is
 * the one honest exception: avgRating is computed from a separate ModRating
 * table with no cached column on GameMod, and Prisma's relation-aggregate
 * `orderBy` only supports `_count` (not `_avg`) for to-many relations — there
 * is no cheap DB-side "top rated" ordering to give it. Fetching by downloads
 * and re-sorting by rating WITHIN each page (below) is a documented
 * approximation: "Top Rated" page 2 shows the 25th-48th most-downloaded mods
 * re-ordered by rating, not the true 25th-48th highest-rated mods
 * catalogue-wide. That is honest and fine at today's rating volumes (a small
 * fraction of 32k+ mods have any reviews at all); if ratings ever justify
 * it, add a cached avgRating/ratingCount column on GameMod (maintained by
 * the rating mutation) and give this its own real orderBy.
 */
const ORDER_BY: Record<CatalogSort, Prisma.GameModOrderByWithRelationInput[]> = {
  featured: [{ featured: "desc" }, { downloads: { sort: "desc", nulls: "last" } }, { popularity: "desc" }, { name: "asc" }],
  downloads: [{ downloads: { sort: "desc", nulls: "last" } }, { name: "asc" }],
  latest: [{ createdAt: "desc" }],
  rating: [{ downloads: { sort: "desc", nulls: "last" } }, { name: "asc" }],
};

/**
 * Real, server-side, paginated + searched + sorted catalogue query — the
 * single data source behind every StoreBrowser instance (marketing and
 * portal, cross-game and per-family). Replaces the old
