const FALLBACK: Record<string, TaxKey> = { content: "gameplay", addon: "gameplay", mod: "gameplay", mods: "gameplay" };

const DIRECT_OF: Record<string, TaxKey> = {};
for (const [k, cats] of Object.entries(DIRECT) as [TaxKey, string[]][]) for (const c of cats) DIRECT_OF[c] = k;
// word boundaries where letters of ANY script count as word characters, as Postgres \m/\M do
