/** The same classification as a SQL CASE expression over "GameMod". */
export function classifySql(): Prisma.Sql {
  const cat = Prisma.sql`lower(btrim("category"))`;
  const whens: Prisma.Sql[] = [];
  for (const [k, cats] of Object.entries(DIRECT) as [TaxKey, string[]][]) whens.push(Prisma.sql`WHEN ${cat} IN (${Prisma.join(cats)}) THEN ${k}`);
  for (const [k, re] of RULES) whens.push(Prisma.sql`WHEN "name" ~* ${`\\m(${re})\\M`} THEN ${k}`);
  for (const [k, re] of RULES) whens.push(Prisma.sql`WHEN left(coalesce("description", ''), 400) ~* ${`\\m(${re})\\M`} THEN ${k}`);
  for (const [c, k] of Object.entries(FALLBACK)) whens.push(Prisma.sql`WHEN ${cat} = ${c} THEN ${k}`);
  return Prisma.sql`(CASE ${Prisma.join(whens, " ")} ELSE 'other' END)`;
}

// ── the category index: every public mod's category, computed once per 10 minutes ──
// Classifying runs ~30 regexes over names/descriptions, too slow to repeat per
// request on a 64k-row catalogue, so the result (id, family, category and the
// sort keys only) is held in memory per server process and rebuilt in the
// background after 10 minutes. Counts, top-per-category and category filters
// all read it, so they always agree with each other.
type Row = { id: string; f: string; k: string; d: number | null; c: number; ft: boolean; n: string };
const TTL = 10 * 60 * 1000;
const g = globalThis as unknown as { __nxmTaxIdx?: { at: number; rows: Row[] }; __nxmTaxBuild?: Promise<Row[]> };
async function build(): Promise<Row[]> {
  const rows = await db.$queryRaw<{ id: string; f: string; k: string; d: number | null; c: Date; ft: boolean; n: string }[]>(Prisma.sql`
    SELECT "id", "gameFamily" AS f, ${classifySql()} AS k, "downloads" AS d, "createdAt" AS c, "featured" AS ft, "name" AS n
