/** Categories with their real counts, for one family or every game, largest first ("other" excluded). */
export async function categoryCounts(family?: string): Promise<{ cat: TaxCat; count: number }[]> {
  const by = new Map<string, number>();
  for (const r of await index()) if (!family || r.f === family) by.set(r.k, (by.get(r.k) ?? 0) + 1);
  return TAXONOMY.filter((t) => (by.get(t.key) ?? 0) > 0).map((t) => ({ cat: t, count: by.get(t.key)! })).sort((a, b) => b.count - a.count);
}

/** Share of public mods in a real category (not "other"), for a family or overall. */
export async function coverage(family?: string) {
  const rows = (await index()).filter((r) => !family || r.f === family);
  const other = rows.filter((r) => r.k === "other").length;
  return { total: rows.length, categorized: rows.length - other, pct: rows.length ? (rows.length - other) / rows.length : 0 };
}

/** The most-downloaded mod ids per category (one family, or every game with null). */
export async function topPerCategory(family: string | null, take: number): Promise<Record<string, string[]>> {
  const out: Record<string, Row[]> = {};
  for (const r of await index()) if (!family || r.f === family) (out[r.k] ??= []).push(r);
  return Object.fromEntries(Object.entries(out).map(([k, rs]) => [k, rs.sort(byDl).slice(0, take).map((r) => r.id)]));
