/** Ids of public mods matching a search (the same fields queryCatalogMods searches). */
async function searchIds(q: string, family?: string): Promise<Set<string>> {
  const like = `%${q.replace(/[\\%_]/g, (c) => `\\${c}`)}%`;
  const rows = await db.$queryRaw<{ id: string }[]>(Prisma.sql`
    SELECT "id" FROM "GameMod" WHERE "active" = true AND "upstreamOk" = true
    ${family ? Prisma.sql`AND "gameFamily" = ${family}` : Prisma.empty}
    AND ("name" ILIKE ${like} OR "category" ILIKE ${like} OR "description" ILIKE ${like})`);
  return new Set(rows.map((r) => r.id));
}

/**
