 * total and page. Same public filter and search fields as queryCatalogMods;
 * download sorts put mods without a count LAST (queryCatalogMods' Postgres
 * default puts them first).
 */
export async function queryMods(opts: { key?: TaxKey; family?: string; q?: string; sort?: TaxSort; page?: number; perPage?: number }) {
  const per = opts.perPage ?? 12;
  const q = (opts.q ?? "").trim();
  const hits = q ? await searchIds(q, opts.family) : null;
  const rows = (await index()).filter((r) => (!opts.family || r.f === opts.family) && (!opts.key || r.k === opts.key) && (!hits || hits.has(r.id)));
  const total = rows.length;
  const pages = Math.max(1, Math.ceil(total / per));
  const page = Math.min(Math.max(1, Math.floor(opts.page ?? 1)), pages);
  const ids = rows.sort(CMP[opts.sort ?? "downloads"]).slice((page - 1) * per, page * per).map((r) => r.id);
  return { mods: await cardsByIds(ids), total, page, totalPages: pages, perPage: per };
