export const dl = (x: number | null) => formatDownloads(x);
export const sourceLabel = (s: string) => SOURCE_LABEL[s] ?? s;

/** "today" / "9d ago" / "4 mo ago" / "2 yr ago" from a real upstream timestamp. */
export function ago(iso: string | null | undefined): string | null {
  if (!iso) return null;
  const days = Math.floor((Date.now() - new Date(iso).getTime()) / 86_400_000);
  if (days < 1) return "today";
  if (days < 60) return `${days}d ago`;
  if (days < 730) return `${Math.round(days / 30)} mo ago`;
  return `${Math.round(days / 365)} yr ago`;
}
const daysSince = (iso: string | null) => (iso ? Math.max(0, Math.floor((Date.now() - new Date(iso).getTime()) / 86_400_000)) : 99999);

/** Real total downloads as a counter: {value, dec, suf} for data-au-count. */
export function countParts(total: number): { value: string; dec: number; suf: string } {
  if (total >= 1e9) { const v = total / 1e9; return { value: v.toFixed(v >= 10 ? 0 : 1), dec: v >= 10 ? 0 : 1, suf: "B" }; }
  if (total >= 1e6) { const v = total / 1e6; return { value: v.toFixed(v >= 10 ? 0 : 1), dec: v >= 10 ? 0 : 1, suf: "M" }; }
  if (total >= 1e3) { const v = total / 1e3; return { value: v.toFixed(v >= 10 ? 0 : 1), dec: v >= 10 ? 0 : 1, suf: "K" }; }
  return { value: String(total), dec: 0, suf: "" };
}

