import { unstable_cache } from "next/cache";
import { db } from "./db";
import type { GameMod, GamePlan, Prisma } from "@prisma/client";
import { GAME_DISPLAY, type GameFamily } from "./games";
import { paginate } from "./pagination";

/**
 * Real revalidate window for the two whole-catalogue aggregates below
 * (`listCatalogFamilies`, `totalDownloadsFor`) — both are cheap in isolation
 * today (~25-30ms, confirmed live 2026-09-21) but recomputed from scratch on
 * EVERY /mods, /mods/games/[family], /dashboard/nxlabs, and
 * /dashboard/nxlabs/games/[family] request (these pages are `force-dynamic`,
 * so nothing about the route itself is cached). Neither number needs
 * second-by-second freshness — a mod's `featured`/`downloads` values only
 * change via periodic backfill scripts (scripts/verify-gamemods.ts and
 * friends), never a live user action — so wrapping them in Next's real data
 * cache with a 10-minute window cuts real, repeated DB round trips under
 * concurrent traffic without ever showing stale-by-more-than-10-minutes data.
 */
const CATALOG_AGGREGATE_REVALIDATE_SECONDS = 600;

/** Real page size for StoreBrowser — no longer a total-catalogue ceiling. */
const CATALOG_PAGE_SIZE = 24;
export async function listFeaturedMods(family?: string, take = 8): Promise<ModSummary[]> {
  const rows = await db.gameMod.findMany({
    where: { active: true, upstreamOk: true, featured: true, ...(family ? { gameFamily: family } : {}) },
    orderBy: [{ downloads: { sort: "desc", nulls: "last" } }, { popularity: "desc" }, { name: "asc" }],
    take,
  });
  const aggs = await ratingAggs(rows.map((r) => r.id));
  return rows.map((r) => toSummary(r, aggs.get(r.id)));
}

/**
 * Curated "Most downloaded" rail — real `GameMod.downloads`, DB-side sorted
 * and DB-side filtered to `downloads: { not: null }`. That filter matters:
 * Postgres' default NULLS FIRST for a DESC sort would otherwise put every
 * never-verified (downloads: null) row ahead of real numbers — see the
 * `rust`/`cs2` families, which currently have zero mods with a real
 * `downloads` count and so correctly return an empty array here rather than
 * a page of nulls masquerading as "most downloaded". Omit `family` for a
 * cross-game rail (the NxLabs homepage's curated section).
 */
export async function listTopDownloadedMods(family?: string, take = 8): Promise<ModSummary[]> {
  const rows = await db.gameMod.findMany({
    where: { active: true, upstreamOk: true, downloads: { not: null }, ...(family ? { gameFamily: family } : {}) },
    orderBy: [{ downloads: { sort: "desc", nulls: "last" } }, { name: "asc" }],
    take,
  });
  const aggs = await ratingAggs(rows.map((r) => r.id));
  return rows.map((r) => toSummary(r, aggs.get(r.id)));
}

/**
 * Curated "Recently updated" rail — real `GameMod.upstreamUpdatedAt` only,
 * DB-side sorted desc and filtered to non-null. That filter is the whole
 * point: `upstreamUpdatedAt` is backfilled from each source's OWN API
 * (scripts/backfill-upstream-updated.ts), never derived from this table's
 * own `updatedAt` (which just marks when WE last touched the row — a bulk
 * re-import, a verify pass — and says nothing about the mod's real upstream
 * freshness). A mod that hasn't been backfilled yet has `upstreamUpdatedAt:
 * null` and simply doesn't appear here — never padded in with a guess.
 * Omit `family` for a cross-game rail (the NxLabs homepage's curated
 * section), same convention as listTopDownloadedMods above.
 */
export async function listRecentlyUpdatedMods(family?: string, take = 8): Promise<ModSummary[]> {
  const rows = await db.gameMod.findMany({
    where: { active: true, upstreamOk: true, upstreamUpdatedAt: { not: null }, ...(family ? { gameFamily: family } : {}) },
    orderBy: [{ upstreamUpdatedAt: "desc" }],
    take,
  });
  const aggs = await ratingAggs(rows.map((r) => r.id));
  return rows.map((r) => toSummary(r, aggs.get(r.id)));
}

/**
 * Curated "Top Rated" rail (item 6 of the 2026-09-20 NxLabs overhaul — the
 * fourth curated row alongside Featured/Most Downloaded/Recently Updated).
 * Checked first, per that task's own instruction: `ORDER_BY.rating` above
 * already exists and is StoreBrowser's real, documented "Top Rated" sort for
 * pagination — fetch by real downloads, then re-sort by real `avgRating`
 * within that fetched set, because there is no cached avgRating column to
 * order by at the DB level (see that constant's own comment). This rail
 * reuses the EXACT same query/approximation rather than a stricter
 * "real average across a minimum rating count" query, which would render
 * this row permanently empty everywhere: confirmed live 2026-09-20, the
 * `ModRating` table has zero rows catalogue-wide today. Reusing the same
 * approximation means the row and its "View more" (?sort=rating) destination
 * never disagree, and the moment any mod gets real ratings, it sorts to the
 * front here exactly as it would on that sort's page 1 — never a fabricated
 * ranking, just an honestly-labeled approximation until real rating volume
 * exists.
 */
export async function listTopRatedMods(family?: string, take = 8): Promise<ModSummary[]> {
  const rows = await db.gameMod.findMany({
    where: { active: true, upstreamOk: true, ...(family ? { gameFamily: family } : {}) },
    orderBy: ORDER_BY.rating,
    take: take * 3, // over-fetch so the real-rating re-sort below has room to surface any rated mods
  });
  const aggs = await ratingAggs(rows.map((r) => r.id));
  return rows
    .map((r) => toSummary(r, aggs.get(r.id)))
    .sort((a, b) => (b.avgRating ?? -1) - (a.avgRating ?? -1) || b.ratingCount - a.ratingCount)
    .slice(0, take);
}

/** Real category breakdown for one family, for the per-family page's chips — a DB-wide groupBy, not just what's on the current page. */
export async function listCategoryCounts(family: string): Promise<{ category: string; count: number }[]> {
  const rows = await db.gameMod.groupBy({
    by: ["category"],
    where: { active: true, upstreamOk: true, gameFamily: family },
    _count: true,
  });
  return rows.map((r) => ({ category: r.category, count: r._count })).sort((a, b) => b.count - a.count);
}

/** Real total downloads across a whole family (or the whole catalogue) — a DB aggregate, not a reduce over one loaded page. */
export const totalDownloadsFor = unstable_cache(
  async (family?: string): Promise<number> => {
    const agg = await db.gameMod.aggregate({
      where: { active: true, upstreamOk: true, ...(family ? { gameFamily: family } : {}) },
      _sum: { downloads: true },
    });
    return agg._sum.downloads ?? 0;
  },
  ["mods-catalog:totalDownloadsFor"],
  { revalidate: CATALOG_AGGREGATE_REVALIDATE_SECONDS }
);

/** Every {family, slug} pair eligible for a public page — feeds generateStaticParams + sitemap.ts. */
export async function listCatalogSlugs(): Promise<{ family: string; slug: string }[]> {
  const rows = await db.gameMod.findMany({
    where: { active: true, upstreamOk: true },
    select: { gameFamily: true, slug: true },

