          <Pager page={page} totalPages={totalPages} total={total} rangeFrom={rangeFrom} rangeTo={rangeTo} hrefFor={hrefFor} />
        </>
      )}
      </div>
    </div>
  );
}

/** Real Prev/Next + numbered pager, plus honest "X–Y of N mods" copy — no fake page counts. */
function Pager({
  page,
  totalPages,
  total,
  rangeFrom,
  rangeTo,
  hrefFor,
}: {
  page: number;
  totalPages: number;
  total: number;
  rangeFrom: number;
  rangeTo: number;
  hrefFor: (next: { page: number }) => string;
}) {
  const linkCls =
    "inline-flex h-9 min-w-9 items-center justify-center gap-1.5 rounded-lg border border-white/10 bg-white/[0.03] px-3 text-sm font-medium text-[var(--fg-muted)] transition-colors hover:border-brand-400/50 hover:text-[var(--fg)]";
  const disabledCls =
    "inline-flex h-9 min-w-9 items-center justify-center gap-1.5 rounded-lg border border-white/[0.06] bg-transparent px-3 text-sm font-medium text-[var(--fg-muted)]/40 cursor-not-allowed";

  const windowStart = Math.max(1, page - 2);
  const windowEnd = Math.min(totalPages, page + 2);
  const pages: number[] = [];
  for (let i = windowStart; i <= windowEnd; i++) pages.push(i);

  const pageHrefFor = (next: { page: number }) => `${hrefFor(next)}#nxlabs-results`;

  return (
    <div className="mt-8 flex flex-col items-center gap-3">
      <p className="text-xs text-[var(--fg-muted)]">
        {total === 0 ? "0 mods" : `${rangeFrom.toLocaleString()}–${rangeTo.toLocaleString()} of ${total.toLocaleString()} mods`}
      </p>
      {totalPages > 1 && (
        <nav className="flex flex-wrap items-center justify-center gap-2" aria-label="Mods pagination">
          {page > 1 ? (
            <Link href={pageHrefFor({ page: page - 1 })} rel="prev" className={linkCls} aria-label="Previous page">
              <IconArrow size={13} className="rotate-180" /> Prev
            </Link>
          ) : (
            <span className={disabledCls} aria-hidden>
              <IconArrow size={13} className="rotate-180" /> Prev
            </span>
          )}

          {windowStart > 1 && (
            <>
              <Link href={pageHrefFor({ page: 1 })} className={linkCls}>
                1
              </Link>
              {windowStart > 2 && <span className="px-1 text-[var(--fg-muted)]">…</span>}
            </>
          )}

          {pages.map((n) =>
            n === page ? (
              <span
                key={n}
                aria-current="page"
                className="inline-flex h-9 min-w-9 items-center justify-center rounded-lg border border-brand-500/50 bg-brand-500/15 px-3 text-sm font-semibold text-brand-300"
              >
                {n}
              </span>
            ) : (
              <Link key={n} href={pageHrefFor({ page: n })} className={linkCls}>
                {n}
              </Link>
            )
          )}

          {windowEnd < totalPages && (
            <>
              {windowEnd < totalPages - 1 && <span className="px-1 text-[var(--fg-muted)]">…</span>}
              <Link href={pageHrefFor({ page: totalPages })} className={linkCls}>
                {totalPages}
              </Link>
            </>
          )}

          {page < totalPages ? (
            <Link href={pageHrefFor({ page: page + 1 })} rel="next" className={linkCls} aria-label="Next page">
              Next <IconArrow size={13} />
            </Link>
          ) : (
            <span className={disabledCls} aria-hidden>
              Next <IconArrow size={13} />
            </span>
          )}
        </nav>
      )}
    </div>
  );
}

