const NOUN = ["Chests", "Villagers", "Biomes", "Backpacks", "Furnaces", "Warps", "Homes", "Shops", "Claims", "Dungeons", "Mobs", "Dragons", "Pipes", "Belts", "Torches", "Maps", "Chat", "Ranks", "Economy", "Lag Fix", "Ores", "Swords", "Boats", "Trees", "Structures", "Skins", "Shaders", "Quests", "Pets", "Doors"];
const SUF = ["", "", " Plus", " Reborn", " Lite", " API", " Core", " Extended", " Redux", " 2"];
const CATS = ["Mods", "Mods", "Mods", "Plugins", "Modpacks", "Performance", "Admin & Permissions", "Economy", "World", "Gameplay", "Chat & Discord", "Datapacks", "Resource Packs"];
const DESCS = [
  "Adds smarter storage with search and sorting, fully server-side.",
  "Optimises entity ticking so busy servers keep a steady TPS.",
  "Land claims and protection that players can manage themselves.",
  "A lightweight economy with shops, auctions and daily rewards.",
  "New structures and biomes that generate naturally in fresh chunks.",
  "Proximity voice chat that works without a client-side launcher.",
  "Quality-of-life tweaks: sort inventories, stack more, find items fast.",
  "Hundreds of new creatures with their own behaviours and drops.",
];
const LOCAL_ICONS = ["/games/art/minecraft_logo.png", "/games/art/valheim_logo.png", "/games/art/rust_logo.png", "/games/art/palworld_logo.png", "/games/art/terraria_logo.png", "/games/art/factorio_logo.png"];
const LOCAL_GALLERY = ["/games/art/minecraft_hero.jpg", "/games/art/valheim_hero.jpg", "/games/art/rust_hero.jpg", "/games/art/palworld_hero.jpg", "/games/art/factorio_hero.jpg", "/games/art/terraria_hero.jpg"];
const BROKEN = "https://broken-image.invalid/nope.png";
const MC_VERSIONS = ["1.21.4", "1.21.1", "1.21", "1.20.6", "1.20.4", "1.20.1", "1.19.4", "1.19.2", "1.18.2", "1.16.5", "1.12.2", "24w14a"];

const FAMILIES: { f: string; n: number; sources: string[]; loaders: string[]; versions?: string[] }[] = [
  { f: "minecraft", n: 2600, sources: ["modrinth", "modrinth", "spigotmc", "hangar"], loaders: ["fabric", "forge", "neoforge", "quilt", "paper", "spigot", "purpur", "datapack"], versions: MC_VERSIONS },
  { f: "valheim", n: 220, sources: ["thunderstore"], loaders: ["bepinex"] },
  { f: "rust", n: 160, sources: ["umod", "codefling"], loaders: ["oxide", "carbon"] },
  { f: "palworld", n: 120, sources: ["nexus", "github"], loaders: [] },
  { f: "factorio", n: 240, sources: ["factorio_portal"], loaders: [], versions: ["2.0", "1.1", "1.0"] },
  { f: "terraria", n: 60, sources: ["github"], loaders: ["tshock"] },
  { f: "cs2", n: 90, sources: ["github"], loaders: ["counterstrikesharp"] },
];

async function main() {
  const [{ current_database }] = await db.$queryRaw<{ current_database: string }[]>`select current_database()`;
  if (current_database !== "nxeon_agt_nxlabs") throw new Error("refusing: connected to " + current_database);

  await db.serverMod.deleteMany({});
  await db.modRating.deleteMany({});
  await db.gameMod.deleteMany({});

  const rows: any[] = [];
  let i = 0;
  for (const fam of FAMILIES) {
    const used = new Set<string>();
    for (let k = 0; k < fam.n; k++) {
      let name = `${pick(ADJ)} ${pick(NOUN)}${pick(SUF)}`;
      while (used.has(name)) name += " " + (k % 9);
      used.add(name);
      const slug = name.toLowerCase().replace(/[^a-z0-9]+/g, "-").replace(/^-|-$/g, "") + "-" + k;
      const loaders = fam.loaders.length ? Array.from(new Set([pick(fam.loaders), ...(chance(0.4) ? [pick(fam.loaders)] : [])])) : [];
      const versions = fam.versions ? MC_VERSIONS.filter(() => chance(0.45)).filter((v) => fam.versions!.includes(v)) : [];
      const iconRoll = rnd();
      const iconUrl = iconRoll < 0.45 ? pick(LOCAL_ICONS) : iconRoll < 0.53 ? BROKEN : null;
      const galRoll = rnd();
      const galleryUrls = galRoll < 0.3 ? [pick(LOCAL_GALLERY), pick(LOCAL_GALLERY)] : galRoll < 0.36 ? [BROKEN] : [];
      const dlRoll = rnd();
      rows.push({
        gameFamily: fam.f,
        name,
        slug,
        category: fam.f === "minecraft" ? pick(CATS) : pick(["Mods", "Gameplay", "QoL", "Admin", "Economy", "Content"]),
        source: pick(fam.sources),
        sourceId: slug,
        url: `https://example.invalid/${fam.f}/${slug}`,
        appliesToVariant: fam.f === "minecraft" && loaders.includes("paper") && chance(0.6) ? "paper" : null,
        description: chance(0.86) ? pick(DESCS) : null,
        iconUrl,
        galleryUrls,
        popularity: Math.floor(rnd() * 1000),
        featured: chance(0.025),
        downloads: dlRoll < 0.1 ? null : Math.floor(Math.exp(rnd() * 18)),
        loaders,
        gameVersions: versions,
        fileBytes: chance(0.8) ? Math.floor(rnd() * 40_000_000) : null,
        serverSide: pick(["required", "optional", null]),
        impact: pick(["light", "light", "moderate", "heavy"]),
        verifiedAt: chance(0.7) ? new Date(Date.now() - rnd() * 30 * 86400e3) : null,
        license: pick(["MIT", "GPL-3.0-only", "All Rights Reserved", null]),
        authorName: chance(0.7) ? pick(["modmuss50", "jellysquid", "Kneelawk", "Draylar", "lumi", "Vex"]) : null,
        longDescription: chance(0.3) ? `## About\n\n${pick(DESCS)}\n\n### Features\n\n- Works on dedicated servers\n- Configurable through a simple file\n- No client install needed\n\n> Tip: back up your world before installing.` : null,
        upstreamUpdatedAt: chance(0.8) ? new Date(Date.now() - rnd() * 600 * 86400e3) : null,
        createdAt: new Date(Date.now() - rnd() * 200 * 86400e3),
      });
      i++;
    }
  }
  for (let k = 0; k < rows.length; k += 500) await db.gameMod.createMany({ data: rows.slice(k, k + 500) });
  console.log("mods", await db.gameMod.count());

  // Plans / templates / user / servers
  const os = await db.osTemplate.upsert({ where: { slug: "ubuntu-24-04" }, update: {}, create: { slug: "ubuntu-24-04", name: "Ubuntu 24.04 LTS", vmid: 9000 } });
  const plan = await db.plan.upsert({ where: { slug: "nano" }, update: {}, create: { slug: "nano", name: "Nano", cpuCores: 1, ramMB: 1024, diskGB: 15, priceCents: 649 } });
  const gp: Record<string, string> = {};
  for (const [fam, name, ram, price] of [["minecraft", "Minecraft 4GB", 4096, 899], ["minecraft", "Minecraft 8GB", 8192, 1599], ["valheim", "Valheim 4GB", 4096, 999], ["rust", "Rust 8GB", 8192, 1899]] as const) {
    const existing = await db.gamePlan.findFirst({ where: { name } });
    const row = existing ?? (await db.gamePlan.create({ data: { gameFamily: fam, name, ramMB: ram, diskGB: 40, priceCents: price, basePlanId: plan.id, active: true } }));
    gp[fam] ??= row.id;
  }
  const email = "labs@sandbox.test";
  const user = await db.user.upsert({ where: { email }, update: {}, create: { email, name: "Labs Tester", passwordHash: await bcrypt.hash("sandbox-pass-123", 10), emailVerifiedAt: new Date() } as any });
  await db.server.deleteMany({ where: { userId: user.id } });
  const mk = (name: string, fam: string, variant: string | null, status = "RUNNING") =>
    db.server.create({ data: { name, hostname: name.toLowerCase().replace(/\s+/g, "-"), label: name, userId: user.id, planId: plan.id, osTemplateId: os.id, gamePlanId: gp[fam], gameVariant: variant, status } as any });
  const smp = await mk("Survival SMP", "minecraft", "paper");
  const fab = await mk("Fabric Lab", "minecraft", "fabric", "STOPPED");
  const vik = await mk("Viking Realm", "valheim", null);

  const mcMods = await db.gameMod.findMany({ where: { gameFamily: "minecraft" }, take: 8, orderBy: { downloads: { sort: "desc", nulls: "last" } } });
  const vMods = await db.gameMod.findMany({ where: { gameFamily: "valheim" }, take: 3 });
  const sm = [
    ...mcMods.slice(0, 4).map((m) => ({ serverId: smp.id, modId: m.id, status: "INSTALLED", version: "1.4.2" })),
    { serverId: smp.id, modId: mcMods[4].id, status: "INSTALLING" },
    { serverId: fab.id, modId: mcMods[5].id, status: "FAILED", error: "Download returned 404 from the source." },
    { serverId: fab.id, modId: mcMods[6].id, status: "INSTALLED" },
    ...vMods.map((m) => ({ serverId: vik.id, modId: m.id, status: "INSTALLED" })),
  ];
  await db.serverMod.createMany({ data: sm });
  console.log("user", user.id, "servers", smp.id, fab.id, vik.id);
}
main().finally(() => db.$disconnect());

