import "server-only";
import { db } from "@/lib/db";
import { familyFor } from "@/lib/game-config";
import { installSupport } from "@/lib/mod-install-support";
import { buildHref } from "@/lib/pagination";
import {
  queryCatalogMods,
  type CatalogPage,
  type CatalogSort,
  type ModSummary,
} from "@/lib/mods-catalog";
import { TAX, isTaxKey, queryMods, topPerCategory, type TaxKey } from "@/app/nxm/_data/mods-taxonomy";

/**
 * NX Labs (customer portal) — the one place the portal's browse pages turn URL
 * search params into a catalogue query.
 *
 * Every read goes through the SHARED catalogue layer — lib/mods-catalog.ts's
 * queryCatalogMods (public = active && upstreamOk, the same rule marketing
 * uses) and, for the category filter, the marketing site's own NxLabs taxonomy
 * (app/nxm/_data/mods-taxonomy.ts), so a category means the same thing on
 * /mods and in the portal. Nothing here reads GameMod directly: when the
 * catalogue gets new rows, images or compat data, these pages pick them up
 * with no change here.
 *
 * Filters are URL state (shareable, back-button safe, server-side):
 *   q        search (name / category / description)
 *   sort     featured | downloads | updated | latest | rating
 *   cat      NxLabs taxonomy key (performance, admin, …)
 *   loader   a GameMod.loaders value (fabric, paper, bepinex, …)
 *   version  a GameMod.gameVersions value (per-game pages only)
 *   game     a family (cross-game hub only)
 *   category the source's raw category — kept because older links use it
 *   page     1-based
 */

export type LabsSort = CatalogSort;
export const LABS_SORTS: { key: LabsSort; label: string }[] = [
  { key: "featured", label: "Featured" },
  { key: "downloads", label: "Most downloaded" },
  { key: "updated", label: "Recently updated" },
  { key: "latest", label: "New in NxLabs" },
  { key: "rating", label: "Top rated" },
];
const SORT_KEYS = new Set<string>(LABS_SORTS.map((s) => s.key));

export type LabsParams = {
  q: string;
  sort: LabsSort;
  cat?: TaxKey;
  loader?: string;
  version?: string;
  game?: string;
  category?: string;
  page: number;
};

type Raw = Record<string, string | string[] | undefined>;
const one = (v: string | string[] | undefined) => (Array.isArray(v) ? v[0] : v)?.trim() || undefined;
/** Shell-inert, bounded token for loader/version/game/category values. */
const token = (v: string | undefined, max = 64) => (v && v.length <= max && /^[\p{L}\p{N} ._+&/:'()-]+$/u.test(v) ? v : undefined);

export function parseLabsParams(sp: Raw): LabsParams {
  const sort = one(sp.sort);
  const cat = one(sp.cat);
  const page = Math.max(1, Math.min(10_000, Math.floor(Number(one(sp.page)) || 1)));
  return {
    q: (one(sp.q) ?? "").slice(0, 100),
    sort: sort && SORT_KEYS.has(sort) ? (sort as LabsSort) : "featured",
    cat: cat && isTaxKey(cat) ? cat : undefined,
    loader: token(one(sp.loader)),
    version: token(one(sp.version), 24),
    game: token(one(sp.game), 40),
    category: token(one(sp.category), 80),
    page,
  };
}

/** Anything beyond the default view? (The pages lead with results when so.) */
export function isFiltered(p: LabsParams) {
  return !!(p.q || p.cat || p.loader || p.version || p.game || p.category || p.page > 1 || p.sort !== "featured");
}

/** Same route, with some params changed. `page` resets unless given. */
export function labsHref(base: string, p: LabsParams, next: Partial<Record<keyof LabsParams, string | number | undefined | null>> = {}) {
  const merged: Record<string, string | number | undefined | null> = {
    q: p.q, sort: p.sort === "featured" ? undefined : p.sort, cat: p.cat, loader: p.loader,
    version: p.version, game: p.game, category: p.category, page: undefined,
    ...next,
  };
  if (merged.sort === "featured") merged.sort = undefined;
  return buildHref(base, merged);
}

export const PER_PAGE = 24;

/**
 * The browse query. `family` is the per-game page's fixed family (the hub
 * passes `p.game` instead). The category path uses the taxonomy's in-memory
