export type InstallState = Record<string, { serverId: string; status: string }[]>;

/** The signed-in customer's game servers that take mods (familyFor != null). */
export async function myModServers(userId: string): Promise<LabsServer[]> {
  const rows = await db.server.findMany({
    where: { userId, status: { notIn: ["DELETING"] } },
    include: { osTemplate: true, gamePlan: true },
