export async function installStateFor(serverIds: string[], modIds: string[]): Promise<InstallState> {
  if (!serverIds.length || !modIds.length) return {};
  const rows = await db.serverMod.findMany({
    where: { serverId: { in: serverIds }, modId: { in: modIds }, status: { not: "REMOVED" } },
    select: { serverId: true, modId: true, status: true },
  });
  const out: InstallState = {};
  for (const r of rows) (out[r.modId] ??= []).push({ serverId: r.serverId, status: r.status });
  return out;
}

