export async function myInstalledMods(serverIds: string[]) {
  if (!serverIds.length) return [];
  return db.serverMod.findMany({
    where: { serverId: { in: serverIds }, status: { not: "REMOVED" } },
    include: { mod: { select: { id: true, name: true, slug: true, gameFamily: true, iconUrl: true, category: true, description: true, source: true, active: true, upstreamOk: true } } },
    orderBy: [{ updatedAt: "desc" }],
  });
