export function installTargets(mod: Pick<ModSummary, "gameFamily" | "appliesToVariant" | "source">, servers: LabsServer[]) {
  const eligible = servers.filter((s) => s.family === mod.gameFamily && (!mod.appliesToVariant || !s.variant || s.variant === mod.appliesToVariant));
  const support = installSupport(mod.gameFamily, mod.source);
  return {
    servers: eligible.map((s) => ({ id: s.id, name: s.name, status: s.status })),
    supported: support.ok,
    unsupportedReason: support.ok ? null : support.message,
  };
}

