    return queryCatalogMods({ family: fam, q: p.q, sort: p.sort, page: p.page, perPage: PER_PAGE, loader: p.loader, gameVersion: p.version, category: p.category, ids });
  }
  return queryCatalogMods({ family: fam, q: p.q, sort: p.sort, page: p.page, perPage: PER_PAGE, loader: p.loader, gameVersion: p.version, category: p.category });
}

export const catLabel = (k: string | undefined) => (k && TAX[k] ? TAX[k].label : undefined);

// ── the viewer's servers + what is on them ──────────────────────────────────

