"use client";

import { useEffect, useRef, useState } from "react";

/**
 * A remote catalogue image (mod icon, gallery shot) that can never show up
 * broken. Mod art is hotlinked from whichever source verified the mod
 * (Modrinth's CDN, Thunderstore, SpigotMC…) — plenty of rows have none, and
 * some point at images that have since gone. So:
 *   - lazy + async-decoded, with no referrer (some CDNs refuse hotlinks with one);
 *   - invisible until it has actually decoded, then fades in over whatever is
 *     underneath (the category gradient art / the monogram) — that underlay IS
 *     the placeholder, so there's no grey box and no layout shift (the caller
 *     sizes the box, this only fills it);
 *   - on error it removes itself entirely and the underlay simply stays.
 *
 * An image that finished loading before React hydrated never fires onLoad, so
 * the mount effect checks `complete` itself.
 */
export function LabsImg({
  src, alt = "", className = "", eager = false,
}: {
  src: string | null | undefined;
  alt?: string;
  className?: string;
  /** Above-the-fold hero art: load immediately. */
  eager?: boolean;
}) {
  const ref = useRef<HTMLImageElement>(null);
  const [state, setState] = useState<"loading" | "ok" | "error">("loading");

  useEffect(() => {
    const el = ref.current;
    if (!el || !el.complete) return;
    setState(el.naturalWidth > 0 ? "ok" : "error");
  }, [src]);

  if (!src || state === "error") return null;
  return (
    // eslint-disable-next-line @next/next/no-img-element -- remote catalogue art from many CDNs; next/image needs every host allow-listed
    <img
      ref={ref}
      src={src}
      alt={alt}
      loading={eager ? "eager" : "lazy"}
      decoding="async"
      referrerPolicy="no-referrer"
      draggable={false}
      onLoad={() => setState("ok")}
      onError={() => setState("error")}
      data-state={state}
      className={"nxl-img " + className}
    />
  );
}

