"use client";

import { createContext, useContext, useTransition } from "react";
import { useRouter } from "next/navigation";

/**
 * Filter/sort/page changes on the NX Labs browse pages are plain URLs (the
 * server does the filtering), so every control is a real link that works with
 * no JavaScript at all. With JavaScript, this makes them feel instant instead
 * of like a page load: the navigation runs inside a transition, the current
 * results stay on screen (dimmed, with a progress hairline) until the new
 * ones are ready, and the page doesn't jump to the top.
 */
type Nav = { pending: boolean; go: (href: string, opts?: { scrollTo?: string }) => void };
const Ctx = createContext<Nav>({ pending: false, go: (href) => { window.location.href = href; } });
export const useLabsNav = () => useContext(Ctx);

export function LabsNavProvider({ children }: { children: React.ReactNode }) {
  const router = useRouter();
  const [pending, start] = useTransition();
  const go: Nav["go"] = (href, opts) => {
    if (opts?.scrollTo) {
      const el = document.getElementById(opts.scrollTo);
      if (el && el.getBoundingClientRect().top < 0) el.scrollIntoView({ block: "start" });
    }
    start(() => router.push(href, { scroll: false }));
  };
  return <Ctx.Provider value={{ pending, go }}>{children}</Ctx.Provider>;
}

/** A link that navigates through the provider (plain <a> without JS). */
export function LabsLink({
  href, scrollTo, className, children, ...rest
}: { href: string; scrollTo?: string; className?: string; children: React.ReactNode } & Omit<React.AnchorHTMLAttributes<HTMLAnchorElement>, "href">) {
  const { go } = useLabsNav();
  return (
    <a
      href={href}
      className={className}
      onClick={(e) => {
        if (e.defaultPrevented || e.button !== 0 || e.metaKey || e.ctrlKey || e.shiftKey || e.altKey) return;
        e.preventDefault();
        go(href, { scrollTo });
      }}
      {...rest}
    >
      {children}
    </a>
  );
}

/** Wraps the results: dims them and shows a hairline while a navigation is in flight. */
export function LabsPending({ children, className = "" }: { children: React.ReactNode; className?: string }) {
  const { pending } = useLabsNav();
  return (
    <div className={"relative " + className} data-pending={pending ? "1" : undefined} aria-busy={pending || undefined}>
      <span className="nxl-progress" aria-hidden />
      <div className="nxl-pending-body">{children}</div>
    </div>
  );
}

