"use client";

import { useState } from "react";
import { Icon } from "@/components/nx/Icon";
import { LabsLink, useLabsNav } from "./LabsNav";

export type Facet = { value: string; label: string; count?: number };
export type ToolbarState = {
  q: string; sort: string; cat?: string; loader?: string; version?: string; game?: string; category?: string;
};

/**
 * Search + sort + filters for an NX Labs browse grid. A real GET form: with
 * JavaScript every change navigates in place (LabsNav); without it, Enter or
 * "Apply" submits the same URL. All filtering happens on the server.
 */
export function LabsToolbar({
  base, state, sorts, games, cats, loaders, versions, total, placeholder = "Search mods and plugins",
}: {
  base: string;
  state: ToolbarState;
  sorts: { key: string; label: string }[];
  games?: Facet[];
  cats: Facet[];
  loaders: Facet[];
  versions?: Facet[];
  total: number;
  placeholder?: string;
}) {
  const { go } = useLabsNav();
  const [open, setOpen] = useState(false);
  const [q, setQ] = useState(state.q);

  const hrefWith = (next: Partial<ToolbarState>) => {
    const s = { ...state, ...next };
    const u = new URLSearchParams();
    for (const k of ["q", "game", "cat", "loader", "version", "category", "sort"] as const) {
      const v = s[k];
      if (v && !(k === "sort" && v === "featured")) u.set(k, v);
    }
    const qs = u.toString();
    return `${base}${qs ? `?${qs}` : ""}#browse`;
  };
  const set = (next: Partial<ToolbarState>) => go(hrefWith(next), { scrollTo: "browse" });

  const active: { key: keyof ToolbarState; label: string }[] = [];
  if (state.q) active.push({ key: "q", label: `“${state.q}”` });
  if (state.game) active.push({ key: "game", label: games?.find((g) => g.value === state.game)?.label ?? state.game });
  if (state.cat) active.push({ key: "cat", label: cats.find((c) => c.value === state.cat)?.label ?? state.cat });
  if (state.loader) active.push({ key: "loader", label: loaders.find((l) => l.value === state.loader)?.label ?? state.loader });
  if (state.version) active.push({ key: "version", label: `Version ${state.version}` });
  if (state.category) active.push({ key: "category", label: `Listed as “${state.category}”` });
  const filterCount = active.filter((a) => a.key !== "q").length;

  const select = (name: keyof ToolbarState, label: string, options: Facet[], all: string) =>
    options.length > 0 && (
      <label className="nxl-field">
        <span className="nxl-field-k">{label}</span>
        <select
          name={name}
          value={state[name] ?? ""}
          onChange={(e) => set({ [name]: e.target.value || undefined } as Partial<ToolbarState>)}
          className="nxl-select"
        >
          <option value="">{all}</option>
          {options.map((o) => (
            <option key={o.value} value={o.value}>
              {o.label}{o.count != null ? ` (${o.count.toLocaleString("en-US")})` : ""}
            </option>
          ))}
          {/* A value from an old link that isn't in today's facet list stays selectable. */}
          {state[name] && !options.some((o) => o.value === state[name]) && <option value={state[name]}>{state[name]}</option>}
        </select>
      </label>
    );

  return (
    <form
      method="get"
      action={`${base}#browse`}
      role="search"
      className="nxl-toolbar"
      onSubmit={(e) => { e.preventDefault(); set({ q: q.trim() || undefined }); }}
    >
