"use client";

import { useState } from "react";
import { Icon } from "@/components/nx/Icon";
import { LabsLink, useLabsNav } from "./LabsNav";

export type Facet = { value: string; label: string; count?: number };
export type ToolbarState = {
  q: string; sort: string; cat?: string; loader?: string; version?: string; game?: string; category?: string;
};

/**
 * Search + sort + filters for an NX Labs browse grid. A real GET form: with
 * JavaScript every change navigates in place (LabsNav); without it, Enter or
 * "Apply" submits the same URL. All filtering happens on the server.
 */
export function LabsToolbar({
  base, state, sorts, games, cats, loaders, versions, total, placeholder = "Search mods and plugins",
}: {
  base: string;
  state: ToolbarState;
  sorts: { key: string; label: string }[];
  games?: Facet[];
  cats: Facet[];
  loaders: Facet[];
  versions?: Facet[];
  total: number;
  placeholder?: string;
}) {
  const { go } = useLabsNav();
  const [open, setOpen] = useState(false);
  const [q, setQ] = useState(state.q);

  const hrefWith = (next: Partial<ToolbarState>) => {
    const s = { ...state, ...next };
    const u = new URLSearchParams();
    for (const k of ["q", "game", "cat", "loader", "version", "category", "sort"] as const) {
      const v = s[k];
      if (v && !(k === "sort" && v === "featured")) u.set(k, v);
    }
    const qs = u.toString();
    return `${base}${qs ? `?${qs}` : ""}#browse`;
  };
  const set = (next: Partial<ToolbarState>) => go(hrefWith(next), { scrollTo: "browse" });

  const active: { key: keyof ToolbarState; label: string }[] = [];
  if (state.q) active.push({ key: "q", label: `“${state.q}”` });
  if (state.game) active.push({ key: "game", label: games?.find((g) => g.value === state.game)?.label ?? state.game });
  if (state.cat) active.push({ key: "cat", label: cats.find((c) => c.value === state.cat)?.label ?? state.cat });
  if (state.loader) active.push({ key: "loader", label: loaders.find((l) => l.value === state.loader)?.label ?? state.loader });
  if (state.version) active.push({ key: "version", label: `Version ${state.version}` });
  if (state.category) active.push({ key: "category", label: `Listed as “${state.category}”` });
  const filterCount = active.filter((a) => a.key !== "q").length;

  const select = (name: keyof ToolbarState, label: string, options: Facet[], all: string) =>
    options.length > 0 && (
      <label className="nxl-field">
        <span className="nxl-field-k">{label}</span>
        <select
          name={name}
          value={state[name] ?? ""}
          onChange={(e) => set({ [name]: e.target.value || undefined } as Partial<ToolbarState>)}
          className="nxl-select"
        >
          <option value="">{all}</option>
          {options.map((o) => (
            <option key={o.value} value={o.value}>
              {o.label}{o.count != null ? ` (${o.count.toLocaleString("en-US")})` : ""}
            </option>
          ))}
          {/* A value from an old link that isn't in today's facet list stays selectable. */}
          {state[name] && !options.some((o) => o.value === state[name]) && <option value={state[name]}>{state[name]}</option>}
        </select>
      </label>
    );

  return (
    <form
      method="get"
      action={`${base}#browse`}
      role="search"
      className="nxl-toolbar"
      onSubmit={(e) => { e.preventDefault(); set({ q: q.trim() || undefined }); }}
    >
      <div className="flex flex-col gap-2.5 sm:flex-row sm:items-center">
        <div className="nxl-search flex-1">
          <Icon name="search" size={14} className="nxl-search-ic" />
          <input
            type="search"
            name="q"
            value={q}
            onChange={(e) => setQ(e.target.value)}
            placeholder={placeholder}
            aria-label="Search the catalogue"
            maxLength={100}
            autoComplete="off"
            enterKeyHint="search"
          />
          <button type="submit" className="nxl-search-go">Search</button>
        </div>
        <div className="flex items-center gap-2">
          <button
            type="button"
            className="nxl-filter-btn sm:hidden"
            aria-expanded={open}
            aria-controls="nxl-filters"
            onClick={() => setOpen((v) => !v)}
          >
            <Icon name="filter" size={13} />
            Filters{filterCount ? ` · ${filterCount}` : ""}
          </button>
          <label className="nxl-sort">
            <span className="sr-only">Sort</span>
            <select name="sort" value={state.sort} onChange={(e) => set({ sort: e.target.value })} className="nxl-select">
              {sorts.map((s) => <option key={s.key} value={s.key}>{s.label}</option>)}
            </select>
          </label>
        </div>
      </div>

      <div id="nxl-filters" className={"nxl-filters " + (open ? "is-open" : "")}>
        {games && select("game", "Game", games, "All games")}
        {select("cat", "Category", cats, "All categories")}
        {select("loader", "Loader / platform", loaders, "Any loader")}
        {versions && select("version", "Game version", versions, "Any version")}
        {state.category && <input type="hidden" name="category" value={state.category} />}
        <noscript>
          <button type="submit" className="btn-secondary">Apply</button>
        </noscript>
      </div>

      <div className="flex flex-wrap items-center gap-2 pt-1 text-[12.5px]">
        <span className="font-semibold text-white" aria-live="polite">
          {total.toLocaleString("en-US")} {total === 1 ? "mod" : "mods"}
        </span>
        {active.map((a) => (
          <LabsLink key={a.key} href={hrefWith({ [a.key]: undefined } as Partial<ToolbarState>)} scrollTo="browse" className="nxl-chip is-on" aria-label={`Remove filter ${a.label}`}>
            {a.label} <span aria-hidden>×</span>
          </LabsLink>
        ))}
        {active.length > 1 && (
          <LabsLink href={hrefWith({ q: undefined, game: undefined, cat: undefined, loader: undefined, version: undefined, category: undefined })} scrollTo="browse" className="text-tx-mute underline-offset-2 hover:underline">
            Clear all
          </LabsLink>
        )}
      </div>
    </form>
  );
}

