"use client";

import { useState, useTransition } from "react";
import Link from "next/link";
import { installMod } from "@/lib/actions-mods";
import { Icon } from "@/components/nx/Icon";

/**
 * "Add to my server", portal edition. Installing always goes through the one
 * real path — lib/actions-mods.ts installMod(), which re-checks ownership,
 * family, variant, install support and the one-job-per-server rule — so this
 * only decides what to OFFER:
 *   - the viewer's servers that can take this mod (family + variant, computed
 *     server-side by installTargets()), each with what's already on it;
 *   - nothing installable when the worker can't place this source/game
 *     automatically, with the reason in the customer's words;
 *   - a deploy link when there's no matching server at all.
 * After queueing it links straight to that server's Mods tab, where the
 * install's real progress lives.
 */
export type InstallServer = { id: string; name: string; status: string; installed?: string | null };

const STATE_LABEL: Record<string, string> = {
  INSTALLED: "Installed",
  INSTALLING: "Installing…",
  FAILED: "Install failed",
  REMOVING: "Removing…",
};
const modsTab = (id: string) => `/dashboard/servers/${id}?tab=mods`;

function useInstall(modId: string) {
  const [pending, start] = useTransition();
  const [busyId, setBusyId] = useState<string | null>(null);
  const [done, setDone] = useState<Record<string, true>>({});
  const [error, setError] = useState<{ id: string; msg: string } | null>(null);
  const install = (serverId: string) => {
    setBusyId(serverId);
    setError(null);
    start(async () => {
      try {
        const res = await installMod(serverId, modId);
        if (res.ok) setDone((d) => ({ ...d, [serverId]: true }));
        else setError({ id: serverId, msg: res.error ?? "That didn't work — try again." });
      } catch {
        setError({ id: serverId, msg: "Couldn't reach the server — check your connection and try again." });
      } finally {
        setBusyId(null);
      }
    });
  };
  return { pending, busyId, done, error, install };
}

/** The full install panel (mod detail page). */
export function LabsInstallPanel({
  modId, modName, gameLabel, servers, supported, unsupportedReason, deployHref, downloadSlot,
}: {
  modId: string; modName: string; gameLabel: string;
  servers: InstallServer[];
  supported: boolean; unsupportedReason: string | null;
  deployHref: string | null;
  downloadSlot?: React.ReactNode;
}) {
  const { pending, busyId, done, error, install } = useInstall(modId);
  const [picked, setPicked] = useState<string>(() => servers.find((s) => !s.installed)?.id ?? servers[0]?.id ?? "");
  const sel = servers.find((s) => s.id === picked);
  const selState = sel ? (done[sel.id] ? "INSTALLING" : sel.installed ?? null) : null;

  if (servers.length === 0) {
    return (
      <div className="nxl-note">
        <p>
          You don&apos;t have a {gameLabel} server yet.{" "}
          {deployHref ? <>Deploy one and {modName} installs in one click from here.</> : <>Download it below and upload it to your server in Files.</>}
        </p>
        {deployHref && (
          <Link href={deployHref} className="btn-primary mt-3 inline-flex items-center gap-2">
            <Icon name="plus" size={13} tone="inherit" /> Deploy a {gameLabel} server
          </Link>
        )}
        {downloadSlot && <div className="mt-3">{downloadSlot}</div>}
      </div>
    );
  }

  if (!supported) {
    return (
      <div className="nxl-note">
        <p className="font-semibold text-white">Manual install</p>
        <p className="mt-1">{unsupportedReason}</p>
        <div className="mt-3 flex flex-wrap gap-2">
          {downloadSlot}
          {servers[0] && (
            <Link href={`/dashboard/servers/${servers[0].id}?tab=files`} className="btn-secondary inline-flex items-center gap-1.5">
              <Icon name="folder" size={12} tone="inherit" /> Open Files on {servers[0].name}
            </Link>
          )}
        </div>
      </div>
    );
  }

  return (
    <div className="flex flex-col gap-3">
      <div role="radiogroup" aria-label="Choose a server" className="flex flex-col gap-2">
        {servers.map((s) => {
          const st = done[s.id] ? "INSTALLING" : s.installed ?? null;
          const on = s.id === picked;
          return (
            <button
              key={s.id}
              type="button"
              role="radio"
              aria-checked={on}
              onClick={() => setPicked(s.id)}
              className={"nxl-srv " + (on ? "is-on" : "")}
            >
              <span className="nxl-srv-dot" data-status={s.status} aria-hidden />
              <span className="min-w-0 flex-1 text-left">
                <span className="block truncate text-[13.5px] font-bold text-white">{s.name}</span>
                <span className="block text-[11.5px] text-tx-faint">{s.status === "RUNNING" ? "Running" : s.status.charAt(0) + s.status.slice(1).toLowerCase()}</span>
              </span>
              {st && <span className={"nxl-badge " + (st === "FAILED" ? "is-bad" : st === "INSTALLED" ? "is-ok" : "")}>{STATE_LABEL[st] ?? st}</span>}
            </button>
          );
        })}
      </div>

      {sel && (selState === "INSTALLED" || selState === "INSTALLING" || selState === "REMOVING") ? (
        <Link href={modsTab(sel.id)} className="btn-secondary inline-flex items-center justify-center gap-2">
          {selState === "INSTALLED" ? "Manage in the Mods tab" : "Follow progress in the Mods tab"} <span aria-hidden>→</span>
        </Link>
      ) : (
        <button
          type="button"
          className="btn-primary inline-flex items-center justify-center gap-2"
          disabled={!sel || pending}
          onClick={() => sel && install(sel.id)}
        >
          <Icon name="download" size={13} tone="inherit" />
          {busyId ? "Adding…" : selState === "FAILED" ? `Retry on ${sel?.name}` : `Add to ${sel?.name ?? "server"}`}
        </button>
      )}
      {sel && done[sel.id] && (
        <p className="text-[12.5px] text-[var(--color-mint,#3fd89a)]" role="status">
          Queued — {modName} is being installed on {sel.name}. The server restarts to load it.
        </p>
      )}
      {error && <p className="text-[12.5px] text-red-400" role="alert">{error.msg}</p>}
      {downloadSlot}
    </div>
  );
}

/** Card footer control: one tap when there's one server, a short list when there are several. */
export function LabsQuickAdd({
  modId, servers, supported, unsupportedReason,
}: {
  modId: string; servers: InstallServer[]; supported: boolean; unsupportedReason: string | null;
}) {
  const { busyId, done, error, install } = useInstall(modId);
  const [open, setOpen] = useState(false);
  if (servers.length === 0) return null;
  if (!supported) {
    return <span className="nxl-mini-note" title={unsupportedReason ?? undefined}>Manual install</span>;
  }
  const state = (s: InstallServer) => (done[s.id] ? "INSTALLING" : s.installed ?? null);
  const allOn = servers.every((s) => state(s) === "INSTALLED" || state(s) === "INSTALLING");

  if (servers.length === 1) {
    const s = servers[0];
    const st = state(s);
    if (st && st !== "FAILED") {
      return <Link href={modsTab(s.id)} className="nxl-badge is-ok">{STATE_LABEL[st] ?? st}</Link>;
    }
    return (
      <span className="flex min-w-0 flex-col items-end gap-1">
        <button type="button" className="nxl-add" disabled={!!busyId} onClick={() => install(s.id)} title={`Add to ${s.name}`}>
          <Icon name="plus" size={11} tone="inherit" /> {busyId ? "Adding…" : st === "FAILED" ? "Retry" : "Add"}
        </button>
        {error && <span className="max-w-[180px] text-right text-[11px] leading-tight text-red-400" role="alert">{error.msg}</span>}
      </span>
    );
  }

  return (
    <div className="relative">
      <button type="button" className={"nxl-add " + (allOn ? "is-done" : "")} aria-expanded={open} onClick={() => setOpen((v) => !v)}>
        <Icon name={allOn ? "check" : "plus"} size={11} tone="inherit" /> {allOn ? "On your servers" : "Add"}
      </button>
      {open && (
        <div className="nxl-pop" role="menu">
          {servers.map((s) => {
            const st = state(s);
            return st && st !== "FAILED" ? (
              <Link key={s.id} href={modsTab(s.id)} className="nxl-pop-row" role="menuitem">
                <span className="truncate">{s.name}</span>
                <span className="nxl-badge is-ok">{STATE_LABEL[st] ?? st}</span>
              </Link>
            ) : (
              <button key={s.id} type="button" className="nxl-pop-row" role="menuitem" disabled={!!busyId} onClick={() => install(s.id)}>
                <span className="truncate">{s.name}</span>
                <span className="text-[11px] font-bold text-brand-300">{busyId === s.id ? "Adding…" : st === "FAILED" ? "Retry" : "Add"}</span>
              </button>
            );
          })}
          {error && <p className="px-2 pb-1 text-[11px] text-red-400" role="alert">{error.msg}</p>}
        </div>
      )}
    </div>
  );
}

