import Link from "next/link";
import { CARD_ILL, catOf, ago, loaderLabel, sourceLabel } from "@/app/nxm/_data/mods-lib";
import { formatDownloads, type ModSummary } from "@/lib/mods-catalog";
import { LabsImg } from "./LabsImg";

/**
 * One NX Labs catalogue card in the portal — the marketing site's mod card
 * (app/nxm/_data/mods-lib.ts xmodCard: category gradient + white-line
 * illustration banner, the mod's own screenshot over it when it has one, the
 * icon or a monogram, real downloads / last update) rebuilt on Nexion tokens
 * so it follows the portal's light/dark theme.
 *
 * Robust to sparse rows by construction: the banner art and monogram are the
 * placeholder AND the fallback — no image, a dead image, no description and
 * no download count all still render a complete, same-height card.
 */
export function LabsCard({
  mod, href, showGame = false, footer, installedOn = 0, priority = false,
}: {
  mod: ModSummary;
  href: string;
  showGame?: boolean;
  /** Install control (client island) — sits outside the card's link. */
  footer?: React.ReactNode;
  /** How many of the viewer's servers already have it. */
  installedOn?: number;
  priority?: boolean;
}) {
  const c = catOf(mod);
  const dl = formatDownloads(mod.downloads);
  const up = ago(mod.upstreamUpdatedAt);
  const kLine = showGame ? `${mod.gameFamilyLabel} · ${c.label}` : c.label;
  const loaders = (mod.loaders ?? []).slice(0, 2).map(loaderLabel);
  return (
    <article className="nxl-card" style={{ "--c1": c.c1, "--c2": c.c2 } as React.CSSProperties}>
      <Link href={href} className="nxl-card-link" prefetch={false}>
        <div className="nxl-card-art">
          <svg viewBox="0 0 200 110" preserveAspectRatio="xMidYMid slice" aria-hidden dangerouslySetInnerHTML={{ __html: CARD_ILL[c.card] ?? CARD_ILL.core }} />
          <LabsImg src={mod.banner} className="nxl-card-banner" eager={priority} />
          {mod.featured && <span className="nxl-card-flag">Featured</span>}
          {installedOn > 0 && <span className="nxl-card-flag is-on">On {installedOn === 1 ? "your server" : `${installedOn} servers`}</span>}
          <span className="nxl-card-mono" aria-hidden>
            <span>{mod.name.slice(0, 1).toUpperCase()}</span>
            <LabsImg src={mod.iconUrl} className="nxl-card-icon" eager={priority} />
          </span>
        </div>
        <div className="nxl-card-body">
          <p className="nxl-card-k">{kLine}</p>
          <h3 className="nxl-card-t">{mod.name}</h3>
          <p className="nxl-card-d">
            {mod.description || `${c.label === "Other" ? "A" : c.label} add-on for ${mod.gameFamilyLabel}, listed on ${sourceLabel(mod.source)}.`}
          </p>
        </div>
      </Link>
      <div className="nxl-card-foot">
        <span className="flex min-w-0 flex-wrap items-center gap-x-2.5 gap-y-1 text-[11.5px] text-tx-faint">
          {dl ? <span className="font-semibold text-tx-mute"><span className="num">{dl}</span> downloads</span> : <span>{sourceLabel(mod.source)}</span>}
          {up && <span>Updated {up}</span>}
          {!up && loaders.length > 0 && <span>{loaders.join(" · ")}</span>}
          {mod.verified && <span className="nxl-verified" title="Checked against its source">✓ Verified</span>}
        </span>
        {footer}
      </div>
    </article>
  );
}

export function LabsGrid({ children }: { children: React.ReactNode }) {
  return <div className="nxl-grid">{children}</div>;
}

