import { LabsLink } from "./LabsNav";

/** Real Prev / numbered / Next pager with an honest "X–Y of N" line. */
export function LabsPager({
  page, totalPages, total, perPage, hrefFor,
}: {
  page: number; totalPages: number; total: number; perPage: number;
  hrefFor: (page: number) => string;
}) {
  if (total === 0) return null;
  const from = (page - 1) * perPage + 1;
  const to = Math.min(page * perPage, total);
  const start = Math.max(1, page - 2);
  const end = Math.min(totalPages, page + 2);
  const nums: number[] = [];
  for (let i = start; i <= end; i++) nums.push(i);
  const link = (n: number, label: React.ReactNode, extra: Record<string, string> = {}) => (
    <LabsLink key={`${n}-${String(label)}`} href={`${hrefFor(n)}#browse`} scrollTo="browse" className="nxl-pg" {...extra}>
      {label}
    </LabsLink>
  );
  return (
    <div className="mt-6 flex flex-col items-center gap-3">
      {totalPages > 1 && (
        <nav className="flex flex-wrap items-center justify-center gap-1.5" aria-label="Pagination">
          {page > 1 ? link(page - 1, "← Prev", { rel: "prev", "aria-label": "Previous page" }) : <span className="nxl-pg is-off" aria-hidden>← Prev</span>}
          {start > 1 && link(1, "1")}
          {start > 2 && <span className="px-1 text-tx-faint">…</span>}
          {nums.map((n) => (n === page ? <span key={n} className="nxl-pg is-on" aria-current="page">{n}</span> : link(n, String(n))))}
          {end < totalPages - 1 && <span className="px-1 text-tx-faint">…</span>}
          {end < totalPages && link(totalPages, totalPages.toLocaleString("en-US"))}
          {page < totalPages ? link(page + 1, "Next →", { rel: "next", "aria-label": "Next page" }) : <span className="nxl-pg is-off" aria-hidden>Next →</span>}
        </nav>
      )}
      <p className="text-[12px] text-tx-faint">
        {from.toLocaleString("en-US")}–{to.toLocaleString("en-US")} of {total.toLocaleString("en-US")} mods
      </p>
    </div>
  );
}

