  return ((w[0]?.[0] ?? "") + (w[1]?.[0] ?? w[0]?.[1] ?? "")).toUpperCase();
}

/** "Browse by what you need" — the NxLabs taxonomy, with real counts. */
export function LabsCategoryTiles({ cats, hrefFor }: { cats: { cat: TaxCat; count: number }[]; hrefFor: (key: string) => string }) {
  return (
    <div className="nxl-cats">
      {cats.map(({ cat, count }) => (
        <Link key={cat.key} href={hrefFor(cat.key)} className="nxl-cat" style={{ "--c1": cat.c1, "--c2": cat.c2 } as React.CSSProperties} prefetch={false}>
          <span className="nxl-cat-art" aria-hidden>
            <svg viewBox="0 0 200 120" preserveAspectRatio="xMidYMid slice" dangerouslySetInnerHTML={{ __html: CARD_ILL[cat.card] ?? CARD_ILL.core }} />
          </span>
          <span className="min-w-0">
            <span className="block truncate text-[13.5px] font-bold text-white">{cat.label}</span>
            <span className="block text-[11.5px] text-tx-faint"><span className="num">{count.toLocaleString("en-US")}</span> mods</span>
          </span>
        </Link>
      ))}
    </div>
  );
}

/** The NX Labs sub-navigation shown under every hero. */
export function LabsTabs({ active, installedCount }: { active: "discover" | "browse" | "installed"; installedCount: number }) {
  const tabs = [
    { key: "discover", label: "Discover", href: "/dashboard/nxlabs", icon: "sparkles" },
    { key: "browse", label: "Browse all", href: "/dashboard/nxlabs?sort=downloads#browse", icon: "grid" },
    { key: "installed", label: "On my servers", href: "/dashboard/nxlabs/installed", icon: "server", n: installedCount },
  ] as const;
  return (
    <nav className="nxl-tabs" aria-label="NX Labs">
      {tabs.map((t) => (
        <Link key={t.key} href={t.href} className={"nxl-tab " + (active === t.key ? "is-on" : "")} aria-current={active === t.key ? "page" : undefined} prefetch={false}>
          <Icon name={t.icon} size={13} tone="inherit" />
          {t.label}
          {"n" in t && t.n > 0 && <span className="nxl-tab-n">{t.n}</span>}
        </Link>
      ))}
    </nav>
  );
}

/** Empty / no-results state with a real next step. */
export function LabsEmpty({ title, body, action }: { title: string; body: string; action?: React.ReactNode }) {
  return (
    <div className="nxl-empty">
      <span className="nxl-empty-ic" aria-hidden><Icon name="search" size={18} tone="inherit" /></span>
      <p className="text-[15px] font-extrabold text-white">{title}</p>
      <p className="max-w-[52ch] text-[12.5px] text-tx-mute">{body}</p>
      {action && <div className="mt-2 flex flex-wrap justify-center gap-2">{action}</div>}
    </div>
  );
}

/** The NX LABS lockup (the marketing site's own asset). */
export function LabsLogo({ className = "" }: { className?: string }) {
  return (
    // eslint-disable-next-line @next/next/no-img-element -- static brand asset
    <img src="/nxm/games/nxlabs_logo.webp" alt="NxLabs" className={"nxl-logo " + className} width={280} height={74} />
  );
}

