  /* .btn-primary — candidate "C3" from the button study: a flat dark face
     bright and far more saturated, which is what made every card read as
     "very blue" rather than as a dark panel with a lit edge. Pulled down to
     sit near the measurement while keeping the same top-left-to-bottom-right
     falloff, so cards still have a defined edge without the blue cast. */
  .card {
    position: relative;
    padding: 1.25rem;
    border-radius: var(--radius-card);
    background:
      linear-gradient(var(--color-surface), var(--color-surface)) padding-box,
