/* NX Labs — customer portal (app/dashboard/nxlabs/**, components/nx/labs/*).
 *
 * Imported only by the NX Labs routes, so none of this reaches marketing,
 * admin or the rest of the portal. Every class is `.nxl-*`-prefixed and sits
 * under `.nxl-root` (the wrapper each NX Labs page renders), and colours come
 * from the portal's own tokens (--color-surface, --color-rim, --color-tx-*),
 * which app/globals.css flips for light mode — so these screens follow the
 * theme toggle without a second palette. The hero banners are
 * `.nx-dark-island` (they sit on game art and stay dark in both themes).
 *
 * The look is the marketing NxLabs pages' (app/nxm/_pages/nxlabs/page.css):
 * category-gradient card banners with white line art, poster game tiles,
 * glass search bar, violet→blue gradient actions — expressed in Nexion tokens.
 *
 * Keyframes are top-level (never nested in a style rule — see CLAUDE.md).
 */
@keyframes nxl-fade { from { opacity: 0; } to { opacity: 1; } }
@keyframes nxl-progress { 0% { transform: translateX(-100%); } 100% { transform: translateX(260%); } }

.nxl-root {
  --nxl-grad: linear-gradient(100deg, #3b6be8, #7b3fef);
  --nxl-glass: rgba(9, 22, 52, 0.55);
  --nxl-line: rgba(140, 180, 255, 0.16);
  --nxl-r: 16px;
}
html[data-theme="light"] .nxl-root:not(.nx-dark-island) {
  --nxl-glass: rgba(255, 255, 255, 0.9);
  --nxl-line: rgba(30, 70, 140, 0.16);
}

/* ── type bits ───────────────────────────────────────────────────────── */
.nxl-root .nxl-eyebrow {
  font-size: 10.5px; font-weight: 800; letter-spacing: .24em; text-transform: uppercase;
  background: linear-gradient(90deg, #6ff0ff, #8c7bff 55%, #d06bff); -webkit-background-clip: text; background-clip: text; color: transparent;
  margin-bottom: 4px;
}
html[data-theme="light"] .nxl-root :not(.nx-dark-island) > .nxl-eyebrow,
html[data-theme="light"] .nxl-root .nxl-eyebrow:not(.nx-dark-island *) {
  background: linear-gradient(90deg, #0b91ab, #5b3fd6 55%, #a3189c); -webkit-background-clip: text; background-clip: text;
}
.nxl-root .nxl-grad-text {
  background: linear-gradient(90deg, #5ce1ff, #6f8dff 45%, #b98cff 80%, #e070ff);
  -webkit-background-clip: text; background-clip: text; color: transparent;
}
.nxl-root .nxl-more {
  display: inline-flex; align-items: center; gap: 6px; font-size: 12.5px; font-weight: 700;
  color: var(--color-brand-300); white-space: nowrap;
}
.nxl-root .nxl-more:hover { color: var(--color-brand-200, #cfaef7); }
html[data-theme="light"] .nxl-root .nxl-more { color: var(--color-violet); }

/* ── hero ────────────────────────────────────────────────────────────── */
.nxl-root .nxl-hero {
  position: relative; overflow: hidden; isolation: isolate;
  border-radius: 20px; border: 1px solid rgba(140, 180, 255, 0.14);
  background: #030816;
}
.nxl-root .nxl-hero-bg { position: absolute; inset: 0; z-index: -2; }
.nxl-root .nxl-hero-bg img { width: 100%; height: 100%; object-fit: cover; }
.nxl-root .nxl-hero::after {
  content: ""; position: absolute; inset: 0; z-index: -1; pointer-events: none;
  background:
    radial-gradient(60% 80% at 50% 0%, rgba(59, 107, 232, .22), transparent 70%),
