}
.nxl-root .nxl-hero.is-game::after {
  background: linear-gradient(90deg, rgba(3, 6, 16, .94) 0%, rgba(3, 6, 16, .72) 46%, rgba(3, 6, 16, .35) 100%),
              linear-gradient(0deg, rgba(3, 6, 16, .9), transparent 50%);
}
.nxl-root .nxl-logo { height: auto; width: min(230px, 62vw); display: block; }
.nxl-root .nxl-hero h1 { color: #fff; }

/* Big glass search (hero) */
.nxl-root .nxl-hsearch {
  display: flex; align-items: center; gap: 8px; width: 100%; max-width: 680px;
  padding: 7px 7px 7px 16px; border-radius: 18px;
  background: rgba(8, 16, 40, .72); border: 1px solid rgba(150, 175, 255, .22);
  box-shadow: inset 0 1px 0 rgba(255,255,255,.06), 0 18px 50px -24px rgba(60, 80, 255, .55);
  backdrop-filter: blur(10px);
}
.nxl-root .nxl-hsearch:focus-within { border-color: rgba(150, 140, 255, .6); }
.nxl-root .nxl-hsearch input {
  flex: 1; min-width: 0; background: transparent; border: 0; outline: 0;
  color: #fff; font-size: 15px; font-weight: 600; padding: 8px 0;
}
.nxl-root .nxl-hsearch input::placeholder { color: #8ea3d6; font-weight: 500; }
.nxl-root .nxl-hsearch select {
  background: rgba(255,255,255,.06); color: #dfe8ff; border: 1px solid rgba(150,175,255,.18);
  border-radius: 11px; font-size: 12.5px; font-weight: 700; padding: 8px 10px; max-width: 150px;
}
.nxl-root .nxl-hsearch select option { color: #0a1829; }
.nxl-root .nxl-gobtn {
  display: inline-flex; align-items: center; gap: 8px; flex: none;
  padding: 11px 18px; border-radius: 13px; font-weight: 800; font-size: 13.5px; color: #fff;
  background: var(--nxl-grad);
  box-shadow: inset 0 1px 0 rgba(255,255,255,.3), 0 10px 26px -12px rgba(92, 80, 255, .95);
}
.nxl-root .nxl-gobtn:hover { filter: brightness(1.08); }
.nxl-root .nxl-hchip {
  display: inline-flex; align-items: center; gap: 6px; padding: 6px 12px; border-radius: 999px;
  font-size: 12px; font-weight: 700; color: #dfe8ff;
  background: rgba(8, 16, 40, .6); border: 1px solid rgba(150, 175, 255, .2);
}
.nxl-root .nxl-hchip:hover { border-color: rgba(150, 140, 255, .55); color: #fff; }
.nxl-root .nxl-stat { display: flex; flex-direction: column; gap: 2px; }
.nxl-root .nxl-stat b { font-size: 22px; font-weight: 800; letter-spacing: -.02em; color: #fff; line-height: 1; }
.nxl-root .nxl-stat span { font-size: 11.5px; color: #93aede; }

/* Side card on the game hero (deploy / your servers) */
.nxl-root .nxl-side {
  border-radius: 18px; padding: 18px; background: rgba(8, 14, 34, .82);
  border: 1px solid rgba(140, 180, 255, .18); backdrop-filter: blur(10px);
  box-shadow: inset 0 1px 0 rgba(255,255,255,.05);
}

/* ── sub-nav tabs ────────────────────────────────────────────────────── */
.nxl-root .nxl-tabs {
  display: flex; gap: 4px; padding: 4px; border-radius: 13px; width: max-content; max-width: 100%;
  overflow-x: auto; scrollbar-width: none;
  background: var(--nxl-glass); border: 1px solid var(--nxl-line);
}
.nxl-root .nxl-tabs::-webkit-scrollbar { display: none; }
.nxl-root .nxl-tab {
  display: inline-flex; align-items: center; gap: 7px; white-space: nowrap;
  padding: 8px 13px; border-radius: 10px; font-size: 12.5px; font-weight: 700; color: var(--color-tx-mute);
}
.nxl-root .nxl-tab:hover { color: var(--color-white); }
.nxl-root .nxl-tab.is-on { color: #fff; background: linear-gradient(120deg, rgba(110,70,240,.9), rgba(56,120,240,.8)); box-shadow: inset 0 1px 0 rgba(255,255,255,.3); }
.nxl-root .nxl-tab-n { font-size: 10.5px; font-weight: 800; padding: 1px 6px; border-radius: 999px; background: rgba(255,255,255,.16); }
.nxl-root .nxl-tab:not(.is-on) .nxl-tab-n { background: rgba(140,58,233,.18); color: var(--color-brand-300); }

/* ── cards ───────────────────────────────────────────────────────────── */
.nxl-root .nxl-grid { display: grid; gap: 14px; grid-template-columns: repeat(auto-fill, minmax(232px, 1fr)); }
@media (max-width: 520px) { .nxl-root .nxl-grid { grid-template-columns: 1fr 1fr; gap: 10px; } }
@media (max-width: 360px) { .nxl-root .nxl-grid { grid-template-columns: 1fr; } }

.nxl-root .nxl-card {
  position: relative; display: flex; flex-direction: column; min-width: 0;
  border-radius: var(--nxl-r); background: var(--color-surface);
  border: 1px solid var(--color-rim);
  box-shadow: 0 2px 8px rgba(0, 3, 10, .35);
  transition: transform .22s cubic-bezier(.16,1,.3,1), border-color .2s, box-shadow .25s;
  content-visibility: auto; contain-intrinsic-size: 300px 320px;
}
.nxl-root .nxl-card:hover { transform: translateY(-3px); border-color: color-mix(in srgb, var(--c1) 55%, var(--color-rim)); box-shadow: 0 18px 40px -22px color-mix(in srgb, var(--c2) 70%, transparent); }
.nxl-root .nxl-card:focus-within { border-color: color-mix(in srgb, var(--c1) 70%, var(--color-rim)); }
.nxl-root .nxl-card-link { display: flex; flex-direction: column; flex: 1; min-width: 0; color: inherit; border-radius: var(--nxl-r) var(--nxl-r) 0 0; }
.nxl-root .nxl-card-link:focus-visible { outline: 2px solid var(--color-brand-400); outline-offset: 2px; }
.nxl-root .nxl-card-art {
  position: relative; aspect-ratio: 200 / 96; border-radius: calc(var(--nxl-r) - 1px) calc(var(--nxl-r) - 1px) 0 0;
  background: linear-gradient(135deg, var(--c1), var(--c2)); overflow: hidden;
}
.nxl-root .nxl-card-art > svg { position: absolute; inset: 0; width: 100%; height: 100%; }
.nxl-root .nxl-card-art::after { content: ""; position: absolute; inset: 0; background: radial-gradient(70% 90% at 92% 0%, rgba(255,255,255,.22), transparent 60%); pointer-events: none; }
.nxl-root .nxl-card-banner { position: absolute; inset: 0; width: 100%; height: 100%; object-fit: cover; }
.nxl-root .nxl-card-flag {
  position: absolute; top: 9px; left: 9px; z-index: 2; font-size: 10px; font-weight: 800; letter-spacing: .06em; text-transform: uppercase;
  color: #fff; padding: 3px 8px; border-radius: 999px; background: rgba(5, 10, 30, .55); backdrop-filter: blur(6px);
}
.nxl-root .nxl-card-flag.is-on { left: auto; right: 9px; background: rgba(17, 200, 142, .85); }
.nxl-root .nxl-card-mono {
  position: absolute; left: 12px; bottom: -18px; z-index: 2; width: 46px; height: 46px; border-radius: 13px; overflow: hidden;
  display: grid; place-items: center; font-size: 19px; font-weight: 800; color: #fff;
  background: linear-gradient(135deg, var(--c1), var(--c2)); border: 3px solid var(--color-surface);
  box-shadow: 0 6px 16px -6px rgba(0,0,0,.5);
}
.nxl-root .nxl-card-mono > span { text-shadow: 0 1px 2px rgba(0,0,0,.3); }
.nxl-root .nxl-card-icon { position: absolute; inset: 0; width: 100%; height: 100%; object-fit: cover; background: var(--color-surface); }
.nxl-root .nxl-card-body { padding: 26px 14px 8px; display: flex; flex-direction: column; gap: 3px; min-width: 0; flex: 1; }
.nxl-root .nxl-card-k { font-size: 10.5px; font-weight: 700; letter-spacing: .04em; text-transform: uppercase; color: var(--color-tx-faint); white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
.nxl-root .nxl-card-t { font-size: 15px; font-weight: 800; letter-spacing: -.015em; line-height: 1.25; color: var(--color-white); overflow: hidden; display: -webkit-box; -webkit-line-clamp: 1; -webkit-box-orient: vertical; }
.nxl-root .nxl-card-d { font-size: 12.5px; line-height: 1.45; color: var(--color-tx-mute); overflow: hidden; display: -webkit-box; -webkit-line-clamp: 2; -webkit-box-orient: vertical; min-height: 2.9em; }
.nxl-root .nxl-card-foot { display: flex; align-items: center; justify-content: space-between; gap: 8px; padding: 9px 14px 12px; border-top: 1px solid var(--color-rim-soft); min-height: 44px; }
.nxl-root .nxl-verified { color: var(--color-mint); font-weight: 700; }

@media (max-width: 520px) {
  .nxl-root .nxl-card-body { padding: 22px 10px 6px; }
  .nxl-root .nxl-card-mono { width: 38px; height: 38px; bottom: -15px; left: 10px; font-size: 16px; border-radius: 11px; }
  .nxl-root .nxl-card-t { font-size: 13.5px; }
  .nxl-root .nxl-card-d { font-size: 11.5px; }
  .nxl-root .nxl-card-foot { padding: 8px 10px 10px; flex-wrap: wrap; }
}

/* Image fade-in: invisible until decoded, the art underneath is the placeholder. */
.nxl-root .nxl-img { opacity: 0; transition: opacity .35s ease; }
.nxl-root .nxl-img[data-state="ok"] { opacity: 1; }
@media (prefers-reduced-motion: reduce) { .nxl-root .nxl-img { transition: none; } }

/* Install controls */
.nxl-root .nxl-add {
  display: inline-flex; align-items: center; gap: 5px; flex: none; padding: 6px 11px; border-radius: 10px;
  font-size: 11.5px; font-weight: 800; color: #fff; background: var(--nxl-grad);
  box-shadow: inset 0 1px 0 rgba(255,255,255,.28), 0 6px 16px -10px rgba(92,80,255,.9);
}
.nxl-root .nxl-add:disabled { opacity: .6; cursor: progress; }
.nxl-root .nxl-add.is-done { background: rgba(17, 200, 142, .16); color: var(--color-mint); box-shadow: none; }
.nxl-root .nxl-badge {
  display: inline-flex; align-items: center; flex: none; white-space: nowrap; padding: 3px 8px; border-radius: 999px;
  font-size: 10.5px; font-weight: 800; color: var(--color-brand-300); background: rgba(140, 58, 233, .14);
}
.nxl-root .nxl-badge.is-ok { color: var(--color-mint); background: rgba(17, 200, 142, .14); }
.nxl-root .nxl-badge.is-bad { color: var(--color-rose, #ef426c); background: rgba(239, 66, 108, .14); }
.nxl-root .nxl-mini-note { font-size: 11px; font-weight: 700; color: var(--color-tx-faint); white-space: nowrap; cursor: help; }
.nxl-root .nxl-pop {
  position: absolute; right: 0; bottom: calc(100% + 6px); z-index: 20; min-width: 210px; padding: 5px;
  border-radius: 12px; background: var(--color-surface); border: 1px solid var(--color-rim-hi);
  box-shadow: 0 20px 40px -18px rgba(0,0,0,.7); animation: nxl-fade .14s ease-out;
}
.nxl-root .nxl-pop-row {
  display: flex; width: 100%; align-items: center; justify-content: space-between; gap: 10px;
  padding: 8px 9px; border-radius: 8px; font-size: 12.5px; font-weight: 700; color: var(--color-white); text-align: left;
}
.nxl-root .nxl-pop-row:hover { background: var(--color-hover); }
.nxl-root .nxl-srv {
  display: flex; align-items: center; gap: 11px; width: 100%; padding: 10px 12px; border-radius: 12px;
  border: 1px solid var(--color-rim); background: var(--color-well, transparent); transition: border-color .15s, background .15s;
}
.nxl-root .nxl-srv:hover { border-color: var(--color-rim-hi); }
.nxl-root .nxl-srv.is-on { border-color: rgba(140, 110, 255, .75); background: rgba(110, 70, 240, .10); box-shadow: inset 0 0 0 1px rgba(140,110,255,.35); }
.nxl-root .nxl-srv-dot { width: 9px; height: 9px; border-radius: 99px; background: var(--color-tx-faint); flex: none; }
.nxl-root .nxl-srv-dot[data-status="RUNNING"] { background: var(--color-mint); box-shadow: 0 0 8px var(--color-mint); }
.nxl-root .nxl-note { border-radius: 12px; padding: 13px 14px; font-size: 13px; line-height: 1.5; color: var(--color-tx-mute); border: 1px solid var(--color-rim); background: var(--color-well, transparent); }

/* ── rails ───────────────────────────────────────────────────────────── */
.nxl-root .nxl-rail {
  display: grid; grid-auto-flow: column; grid-auto-columns: minmax(250px, 1fr); gap: 14px;
  overflow-x: auto; scroll-snap-type: x mandatory; overscroll-behavior-x: contain;
  padding: 2px 2px 14px; margin: 0 -2px; scrollbar-width: thin; scrollbar-color: var(--color-rim-hi) transparent;
}
@media (min-width: 1280px) { .nxl-root .nxl-rail { grid-auto-columns: calc((100% - 3 * 14px) / 4); } }
@media (max-width: 640px) { .nxl-root .nxl-rail { grid-auto-columns: 78%; } }
.nxl-root .nxl-rail-item { scroll-snap-align: start; display: flex; min-width: 0; }
.nxl-root .nxl-rail-item > * { flex: 1; }
.nxl-root .nxl-rail:focus-visible { outline: 2px solid var(--color-brand-400); outline-offset: 4px; border-radius: 12px; }

/* ── game tiles ──────────────────────────────────────────────────────── */
.nxl-root .nxl-games { display: grid; gap: 12px; grid-template-columns: repeat(auto-fill, minmax(150px, 1fr)); }
@media (max-width: 520px) { .nxl-root .nxl-games { grid-template-columns: repeat(3, 1fr); gap: 8px; } }
.nxl-root .nxl-game {
  position: relative; overflow: hidden; aspect-ratio: 3 / 4; border-radius: 14px; isolation: isolate;
  background: linear-gradient(150deg, #1b2f6b, #3a1f78); border: 1px solid rgba(140, 180, 255, .14);
  transition: transform .25s cubic-bezier(.16,1,.3,1), border-color .2s, box-shadow .25s;
}
.nxl-root .nxl-game:hover { transform: translateY(-3px); border-color: rgba(150, 140, 255, .6); box-shadow: 0 18px 36px -20px rgba(110, 80, 255, .9); }
.nxl-root .nxl-game-mono { position: absolute; inset: 0; display: grid; place-items: center; font-size: 30px; font-weight: 900; color: rgba(255,255,255,.35); z-index: -1; }
.nxl-root .nxl-game-img { position: absolute; inset: 0; width: 100%; height: 100%; object-fit: cover; z-index: -1; }
.nxl-root .nxl-game-scrim { position: absolute; inset: 0; background: linear-gradient(0deg, rgba(3,6,16,.92) 0%, rgba(3,6,16,.25) 46%, transparent 70%); }
.nxl-root .nxl-game-meta { position: absolute; left: 10px; right: 10px; bottom: 10px; display: flex; flex-direction: column; gap: 1px; }
.nxl-root .nxl-game-t { font-size: 13px; font-weight: 800; color: #fff; line-height: 1.2; }
.nxl-root .nxl-game-n { font-size: 11px; color: #b9c8ea; }
.nxl-root .nxl-game-mine { position: absolute; top: 8px; left: 8px; font-size: 9.5px; font-weight: 800; text-transform: uppercase; letter-spacing: .06em; color: #fff; padding: 3px 7px; border-radius: 999px; background: rgba(17, 200, 142, .85); }
@media (max-width: 520px) { .nxl-root .nxl-game-t { font-size: 11.5px; } .nxl-root .nxl-game-n { font-size: 10px; } }

/* ── category tiles ──────────────────────────────────────────────────── */
.nxl-root .nxl-cats { display: grid; gap: 10px; grid-template-columns: repeat(auto-fill, minmax(210px, 1fr)); }
@media (max-width: 520px) { .nxl-root .nxl-cats { grid-template-columns: 1fr 1fr; gap: 8px; } }
.nxl-root .nxl-cat {
  display: flex; align-items: center; gap: 11px; min-width: 0; padding: 9px; border-radius: 14px;
  background: var(--color-surface); border: 1px solid var(--color-rim); transition: border-color .2s, transform .2s;
}
.nxl-root .nxl-cat:hover { border-color: color-mix(in srgb, var(--c1) 60%, var(--color-rim)); transform: translateY(-2px); }
.nxl-root .nxl-cat-art { position: relative; flex: none; width: 54px; height: 40px; border-radius: 10px; overflow: hidden; background: linear-gradient(135deg, var(--c1), var(--c2)); }
.nxl-root .nxl-cat-art svg { position: absolute; inset: 0; width: 100%; height: 100%; }

/* ── toolbar ─────────────────────────────────────────────────────────── */
.nxl-root .nxl-toolbar {
  position: sticky; top: calc(var(--nx-header-h, 64px) + 6px); z-index: 15;
  display: flex; flex-direction: column; gap: 10px; padding: 12px; border-radius: 16px;
  background: color-mix(in srgb, var(--color-surface) 88%, transparent); border: 1px solid var(--color-rim);
  backdrop-filter: blur(12px); box-shadow: 0 12px 30px -24px rgba(0,0,0,.8);
}
@media (max-width: 640px) { .nxl-root .nxl-toolbar { position: static; } }
.nxl-root .nxl-search {
  position: relative; display: flex; align-items: center; min-width: 0; border-radius: 12px;
  background: var(--color-well, transparent); border: 1px solid var(--color-rim-hi);
}
.nxl-root .nxl-search:focus-within { border-color: var(--color-brand-400); box-shadow: 0 0 0 3px rgba(140, 58, 233, .18); }
.nxl-root .nxl-search-ic { position: absolute; left: 12px; color: var(--color-tx-faint); pointer-events: none; }
.nxl-root .nxl-search input { flex: 1; min-width: 0; background: transparent; border: 0; outline: 0; padding: 10px 10px 10px 38px; font-size: 13.5px; color: var(--color-white); }
.nxl-root .nxl-search input::placeholder { color: var(--color-tx-faint); }
.nxl-root .nxl-search-go { margin: 4px; padding: 6px 12px; border-radius: 9px; font-size: 12px; font-weight: 800; color: #fff; background: var(--nxl-grad); }
.nxl-root .nxl-select {
  appearance: none; -webkit-appearance: none; width: 100%; min-width: 0; padding: 9px 30px 9px 11px; border-radius: 11px;
  font-size: 12.5px; font-weight: 700; color: var(--color-white); background-color: var(--color-well, transparent);
  border: 1px solid var(--color-rim-hi); cursor: pointer;
  background-image: linear-gradient(45deg, transparent 50%, var(--color-tx-faint) 50%), linear-gradient(135deg, var(--color-tx-faint) 50%, transparent 50%);
  background-position: calc(100% - 15px) 52%, calc(100% - 10px) 52%; background-size: 5px 5px; background-repeat: no-repeat;
}
.nxl-root .nxl-select:focus-visible { outline: 2px solid var(--color-brand-400); outline-offset: 1px; }
.nxl-root .nxl-select option { background: var(--color-surface); color: var(--color-white); }
.nxl-root .nxl-sort { min-width: 170px; flex: 1; }
.nxl-root .nxl-filters { display: grid; gap: 8px; grid-template-columns: repeat(auto-fit, minmax(170px, 1fr)); }
@media (max-width: 639px) { .nxl-root .nxl-filters { display: none; grid-template-columns: 1fr 1fr; } .nxl-root .nxl-filters.is-open { display: grid; } }
.nxl-root .nxl-field { display: flex; flex-direction: column; gap: 4px; min-width: 0; }
.nxl-root .nxl-field-k { font-size: 10.5px; font-weight: 800; letter-spacing: .08em; text-transform: uppercase; color: var(--color-tx-faint); }
.nxl-root .nxl-filter-btn { display: inline-flex; align-items: center; gap: 6px; padding: 9px 12px; border-radius: 11px; font-size: 12.5px; font-weight: 800; color: var(--color-white); border: 1px solid var(--color-rim-hi); background: var(--color-well, transparent); white-space: nowrap; }
.nxl-root .nxl-chip { display: inline-flex; align-items: center; gap: 6px; padding: 4px 10px; border-radius: 999px; font-size: 12px; font-weight: 700; border: 1px solid var(--color-rim-hi); color: var(--color-tx-mute); }
.nxl-root .nxl-chip.is-on { color: var(--color-brand-300); border-color: rgba(140, 58, 233, .5); background: rgba(140, 58, 233, .1); }
html[data-theme="light"] .nxl-root .nxl-chip.is-on { color: var(--color-violet); }

/* Pending navigation: keep results, dim them, run a hairline. */
.nxl-root .nxl-progress { position: absolute; left: 0; right: 0; top: -8px; height: 2px; overflow: hidden; border-radius: 2px; opacity: 0; transition: opacity .2s; pointer-events: none; }
.nxl-root .nxl-progress::after { content: ""; position: absolute; inset: 0; width: 40%; background: var(--nxl-grad); animation: nxl-progress 1s ease-in-out infinite; }
.nxl-root [data-pending] > .nxl-progress { opacity: 1; }
.nxl-root .nxl-pending-body { transition: opacity .2s; }
.nxl-root [data-pending] > .nxl-pending-body { opacity: .5; pointer-events: none; }
@media (prefers-reduced-motion: reduce) { .nxl-root .nxl-progress::after { animation: none; width: 100%; } }

/* Pager */
.nxl-root .nxl-pg { display: inline-flex; align-items: center; justify-content: center; min-width: 36px; height: 36px; padding: 0 11px; border-radius: 10px; font-size: 12.5px; font-weight: 700; color: var(--color-tx-mute); border: 1px solid var(--color-rim); background: var(--color-surface); }
.nxl-root a.nxl-pg:hover { border-color: var(--color-brand-400); color: var(--color-white); }
.nxl-root .nxl-pg.is-on { color: #fff; border-color: transparent; background: var(--nxl-grad); }
.nxl-root .nxl-pg.is-off { opacity: .4; }

/* Empty state */
.nxl-root .nxl-empty { display: flex; flex-direction: column; align-items: center; text-align: center; gap: 6px; padding: 44px 18px; border-radius: 18px; border: 1px dashed var(--color-rim-hi); background: var(--color-surface); }
.nxl-root .nxl-empty-ic { display: grid; place-items: center; width: 44px; height: 44px; border-radius: 13px; margin-bottom: 6px; color: #fff; background: var(--nxl-grad); }

/* ── detail page ─────────────────────────────────────────────────────── */
.nxl-root .nxl-dhero { padding: 26px; }
