"use client";

import { useState, useTransition } from "react";
import { resolveModDownloadAction } from "@/lib/actions-mods";
import { Icon } from "@/components/nx/Icon";

/**
 * Card-sized download control. Same behaviour as components/mods/
 * DownloadButton (the marketing/legacy one): when the server already knows the
 * URL without a network call (`url`), it's a plain link; otherwise the real
 * URL is resolved only when someone actually clicks (Modrinth/Thunderstore
 * need a live API call — resolving 24 of those per page render cost 1–2s).
 */
export function LabsDownload({
  modId, url, label = "Download", className = "nxl-dlbtn",
}: { modId: string; url?: string | null; label?: string; className?: string }) {
  const [pending, start] = useTransition();
  const [resolved, setResolved] = useState<string | null | undefined>(url ?? undefined);

  if (resolved === null) return null;
  if (resolved) {
    return (
      <a href={resolved} target="_blank" rel="noopener noreferrer nofollow" className={className} title={label}>
        <Icon name="download" size={12} tone="inherit" /> <span>{label}</span>
      </a>
    );
  }
  return (
    <button
      type="button"
      className={className}
      disabled={pending}
      title={label}
      onClick={() =>
        start(async () => {
          const r = await resolveModDownloadAction(modId).catch(() => null);
          setResolved(r?.url ?? null);
          if (r?.url) window.open(r.url, "_blank", "noopener,noreferrer");
        })
      }
    >
      <Icon name="download" size={12} tone="inherit" /> <span>{pending ? "Resolving…" : label}</span>
    </button>
  );
}

