import { resolveDownloadUrlSync, type ModSummary } from "@/lib/mods-catalog";
import { LabsCard } from "@/components/nx/labs/LabsCard";
import { LabsQuickAdd } from "@/components/nx/labs/LabsInstall";
import { LabsDownload } from "@/components/nx/labs/LabsDownload";
import { installTargets, type InstallState, type LabsServer } from "./labs";

export const modHref = (m: { gameFamily: string; slug: string }) =>
  `/dashboard/nxlabs/${encodeURIComponent(m.gameFamily)}/${encodeURIComponent(m.slug)}`;

/**
 * A catalogue card with the right footer for THIS viewer: one-tap install
 * when they own a server that can take it, a download otherwise. All the
 * eligibility is computed here on the server; the client island only renders
 * it and calls installMod().
 */
export function labsCard(
  m: ModSummary,
  ctx: { servers: LabsServer[]; state: InstallState; showGame?: boolean; priority?: boolean }
) {
  const t = installTargets(m, ctx.servers);
  const rows = ctx.state[m.id] ?? [];
  const servers = t.servers.map((s) => ({ ...s, installed: rows.find((r) => r.serverId === s.id)?.status ?? null }));
  const installedOn = rows.filter((r) => r.status === "INSTALLED" || r.status === "INSTALLING").length;
  const sync = resolveDownloadUrlSync(m);
  const footer = servers.length > 0
    ? <LabsQuickAdd modId={m.id} servers={servers} supported={t.supported} unsupportedReason={t.unsupportedReason} />
    : sync === null ? null : <LabsDownload modId={m.id} url={sync?.url ?? null} label={sync && !sync.direct ? "Source" : "Download"} />;
  return (
    <LabsCard key={m.id} mod={m} href={modHref(m)} showGame={ctx.showGame} footer={footer} installedOn={installedOn} priority={ctx.priority} />
  );
}

