import Link from "next/link";
import { requireUser } from "@/lib/auth";
import {
  listFeaturedMods,
  listTopDownloadedMods,
  listRecentlyUpdatedMods,
  listTopRatedMods,
  listLoaderCounts,
  totalDownloadsFor,
  formatDownloads,
  type ModSummary,
} from "@/lib/mods-catalog";
import { families as listFamilies, gameArt, loaderLabel } from "@/app/nxm/_data/mods-lib";
import { categoryCounts } from "@/app/nxm/_data/mods-taxonomy";
import { LabsNavProvider, LabsPending } from "@/components/nx/labs/LabsNav";
import { LabsToolbar } from "@/components/nx/labs/LabsToolbar";
import { LabsGrid } from "@/components/nx/labs/LabsCard";
import { LabsPager } from "@/components/nx/labs/LabsPager";
import { LabsHead, LabsRail, RailItem, LabsGameTiles, LabsCategoryTiles, LabsTabs, LabsEmpty, LabsLogo } from "@/components/nx/labs/LabsBits";
import { Icon } from "@/components/nx/Icon";
import {
  LABS_SORTS, PER_PAGE, catLabel, installStateFor, isFiltered, labsHref, myInstalledMods, myModServers, parseLabsParams, runLabsQuery,
} from "./_lib/labs";
import { labsCard } from "./_lib/cards";
import "./labs.css";

export const dynamic = "force-dynamic";

const BASE = "/dashboard/nxlabs";

/**
 * NX Labs, inside the customer portal — the same catalogue as the public /mods
 * pages, plus what only a signed-in customer gets: what's already on their
 * servers, and one-tap install onto a server that can take each mod.
 *
 * Default view = discovery (featured, games, categories, ranked rails) with the
 * full catalogue browser underneath. Any filter in the URL (search, game,
 * category, loader, sort, page) leads with results instead — a filtered link
 * lands on what it asked for. Every result set is filtered and paginated on
 * the server (24 per page over ~64k rows), and every control is a URL.
 */
export default async function NxLabsPage({ searchParams }: { searchParams: Promise<Record<string, string | string[] | undefined>> }) {
  const user = await requireUser();
  const p = parseLabsParams(await searchParams);
  const filtered = isFiltered(p);

  const [fams, result, totalDl, servers, cats, loaders, featured, top, recent, rated] = await Promise.all([
    listFamilies(),
    runLabsQuery(p),
    totalDownloadsFor(),
    myModServers(user.id),
    categoryCounts(p.game),
    listLoaderCounts(p.game),
    filtered ? [] : listFeaturedMods(undefined, 12),
    filtered ? [] : listTopDownloadedMods(undefined, 12),
    filtered ? [] : listRecentlyUpdatedMods(undefined, 12),
    filtered ? [] : listTopRatedMods(undefined, 12),
  ]);
  const serverIds = servers.map((s) => s.id);
  const shown: ModSummary[] = [...result.mods, ...featured, ...top, ...recent, ...rated];
  const [state, installed] = await Promise.all([
    installStateFor(serverIds, Array.from(new Set(shown.map((m) => m.id)))),
    myInstalledMods(serverIds),
  ]);

  const totalMods = fams.reduce((s, f) => s + f.count, 0);
  const myFamilies = new Set(servers.map((s) => s.family));
  const live = installed.filter((r) => r.status === "INSTALLED" || r.status === "INSTALLING");
  const ctx = { servers, state, showGame: !p.game };
  const games = fams.map((f) => ({ ...f, poster: gameArt(f.family).poster }));
  // Your games first, then by catalogue size — the tiles you'll actually use lead.
  games.sort((a, b) => Number(myFamilies.has(b.family)) - Number(myFamilies.has(a.family)) || b.count - a.count);
  const popular = games.slice(0, 5);

  const rail = (title: string, eyebrow: string, sub: string | undefined, mods: ModSummary[], href: string, id: string) =>
    mods.length > 0 && (
      <section id={id}>
        <LabsHead eyebrow={eyebrow} title={title} sub={sub} href={href} />
        <LabsRail label={title}>
          {mods.map((m) => <RailItem key={m.id}>{labsCard(m, { ...ctx, showGame: true })}</RailItem>)}
        </LabsRail>
      </section>
    );

  return (
    <div className="nxl-root mx-auto flex w-full max-w-[1520px] flex-col gap-8">
      <LabsNavProvider>
        {/* ── hero ─────────────────────────────────────────────────────── */}
        <header className={"nxl-hero nx-dark-island " + (filtered ? "px-5 py-6 sm:px-8" : "px-5 py-9 sm:px-10 sm:py-12")}>
          <div className="nxl-hero-bg" aria-hidden>
