// ── deploy (for a viewer with no matching server) ──────────────────────────

/**
 * The real deploy action for a family, or null when Nxeon doesn't host it —
 * same gate the old portal detail page used: an active GamePlan that clears
 * the mod's impact bar AND a PREVIEW_GAMES entry (the "we host this game"
 * signal behind the live hosting pages). Never offers a plan that isn't real.
 */
export async function deployFor(family: string, impact = "light") {
  const plans = await db.gamePlan.findMany({ where: { gameFamily: family, active: true }, orderBy: { priceCents: "asc" } });
  const plan = recommendedPlanFor({ impact }, plans);
  const preview = (PREVIEW_GAMES as Record<string, PreviewGame>)[family];
  if (!plan || !preview) return null;
  return {
    plan,
    href: deployHref({ service: "game", gameFamily: family, gamePlanId: plan.id, region: preview.deployRegion }),
  };
}
