  const plans = await db.gamePlan.findMany({ where: { gameFamily: family, active: true }, orderBy: { priceCents: "asc" } });
  const plan = recommendedPlanFor({ impact }, plans);
  const preview = (PREVIEW_GAMES as Record<string, PreviewGame>)[family];
  if (!plan || !preview) return null;
  return {
    plan,
    href: deployHref({ service: "game", gameFamily: family, gamePlanId: plan.id, region: preview.deployRegion }),
  };
}
