import Link from "next/link";
import { notFound } from "next/navigation";
import { requireUser } from "@/lib/auth";
import {
  listCatalogFamilies,
  listCategoryCounts,
  listFeaturedMods,
  listTopDownloadedMods,
  listRecentlyUpdatedMods,
  listTopRatedMods,
  listLoaderCounts,
  listGameVersionCounts,
  totalDownloadsFor,
  formatDownloads,
  formatPriceCents,
  type ModSummary,
} from "@/lib/mods-catalog";
import { gameArt, gameLabel, loaderLabel } from "@/app/nxm/_data/mods-lib";
import { categoryCounts } from "@/app/nxm/_data/mods-taxonomy";
import { LabsNavProvider, LabsPending } from "@/components/nx/labs/LabsNav";
import { LabsToolbar } from "@/components/nx/labs/LabsToolbar";
import { LabsGrid } from "@/components/nx/labs/LabsCard";
import { LabsPager } from "@/components/nx/labs/LabsPager";
import { LabsHead, LabsRail, RailItem, LabsCategoryTiles, LabsTabs, LabsEmpty } from "@/components/nx/labs/LabsBits";
import { LabsImg } from "@/components/nx/labs/LabsImg";
import { Icon } from "@/components/nx/Icon";
import {
  LABS_SORTS, PER_PAGE, catLabel, deployFor, installStateFor, isFiltered, labsHref, myInstalledMods, myModServers, parseLabsParams, runLabsQuery,
} from "../../_lib/labs";
import { labsCard } from "../../_lib/cards";
import "../../labs.css";

export const dynamic = "force-dynamic";

/** One game's NX Labs page in the portal — same data as marketing's /mods/games/[family], portal chrome and install. */
export default async function PortalGameModsPage({
  params,
  searchParams,
}: {
  params: Promise<{ family: string }>;
  searchParams: Promise<Record<string, string | string[] | undefined>>;
}) {
  const { family } = await params;
  const user = await requireUser();
  const entry = (await listCatalogFamilies()).find((f) => f.family === family);
  if (!entry) notFound();

  const sp = await searchParams;
  const p = parseLabsParams(sp);
  p.game = undefined; // the family is the route here, not a filter
  const filtered = isFiltered(p);
  const base = `/dashboard/nxlabs/games/${encodeURIComponent(family)}`;

  const [result, totalDl, servers, cats, rawCats, loaders, versions, deploy, featured, top, recent, rated] = await Promise.all([
    runLabsQuery(p, family),
    totalDownloadsFor(family),
    myModServers(user.id),
    categoryCounts(family),
    listCategoryCounts(family),
    listLoaderCounts(family),
    listGameVersionCounts(family),
    deployFor(family),
    filtered ? [] : listFeaturedMods(family, 12),
    filtered ? [] : listTopDownloadedMods(family, 12),
    filtered ? [] : listRecentlyUpdatedMods(family, 12),
    filtered ? [] : listTopRatedMods(family, 12),
  ]);
  const mine = servers.filter((s) => s.family === family);
  const shown: ModSummary[] = [...result.mods, ...featured, ...top, ...recent, ...rated];
  const [state, installed] = await Promise.all([
    installStateFor(mine.map((s) => s.id), Array.from(new Set(shown.map((m) => m.id)))),
    myInstalledMods(servers.map((s) => s.id)),
  ]);
  const ctx = { servers: mine, state, showGame: false };
  const label = gameLabel(family, entry.label);
  const hero = gameArt(family).hero;
  const liveCount = installed.filter((r) => r.status === "INSTALLED" || r.status === "INSTALLING").length;
  const loaderChips = loaders.slice(0, 6);

  const rail = (title: string, eyebrow: string, sub: string | undefined, mods: ModSummary[], href: string, id: string) =>
    mods.length > 0 && (
      <section id={id}>
        <LabsHead eyebrow={eyebrow} title={title} sub={sub} href={href} />
        <LabsRail label={title}>
          {mods.map((m) => <RailItem key={m.id}>{labsCard(m, ctx)}</RailItem>)}
        </LabsRail>
      </section>
    );

  return (
    <div className="nxl-root mx-auto flex w-full max-w-[1520px] flex-col gap-8">
      <LabsNavProvider>
        <header className="nxl-hero is-game nx-dark-island px-5 py-7 sm:px-9 sm:py-10">
          <div className="nxl-hero-bg" aria-hidden>
            <LabsImg src={hero} eager />
          </div>
          <div className="grid items-end gap-6 lg:grid-cols-[1fr_340px]">
            <div className="flex min-w-0 flex-col gap-4">
              <nav aria-label="Breadcrumb" className="flex items-center gap-2 text-[13px] font-semibold text-[#b9c8ea]">
                <Link href="/dashboard/nxlabs" className="hover:text-white" prefetch={false}>NxLabs</Link>
                <span aria-hidden className="text-[#5f7cb4]">/</span>
                <span className="text-white">{label}</span>
              </nav>
              <h1 className="text-[32px] font-extrabold leading-[1.02] tracking-[-0.035em] sm:text-[48px]">
                {label}<br /><span className="nxl-grad-text">mods and plugins</span>
              </h1>
              <p className="max-w-[60ch] text-[14px] leading-[1.55] text-[#b9c8ea]">
                <b className="text-white">{entry.count.toLocaleString("en-US")}</b> verified add-ons, each linked to its real source
                {totalDl > 0 ? <> — <b className="text-white">{formatDownloads(totalDl)}</b> downloads between them</> : null}.
              </p>
              <form method="get" action={`${base}#browse`} role="search" className="nxl-hsearch">
                <Icon name="search" size={15} tone="inherit" className="flex-none text-[#8ea3d6]" />
                <input type="search" name="q" defaultValue={p.q} maxLength={100} autoComplete="off" enterKeyHint="search"
                       placeholder={`Search ${entry.count.toLocaleString("en-US")} ${label} mods`} aria-label={`Search ${label} mods`} />
                <button type="submit" className="nxl-gobtn">Search <span aria-hidden>→</span></button>
              </form>
              {loaderChips.length > 1 && (
                <div className="flex flex-wrap items-center gap-2">
                  <span className="text-[12px] text-[#93aede]">Loaders and platforms</span>
                  {loaderChips.map((l) => (
                    <Link key={l.loader} href={`${base}?loader=${encodeURIComponent(l.loader)}#browse`} className="nxl-hchip" prefetch={false}>
                      {loaderLabel(l.loader)}
                    </Link>
                  ))}
                </div>
              )}
            </div>

            <aside className="nxl-side">
              {mine.length > 0 ? (
                <>
                  <p className="text-[13px] font-extrabold text-white">Your {label} server{mine.length > 1 ? "s" : ""}</p>
                  <ul className="mt-3 flex flex-col gap-2">
                    {mine.map((s) => {
                      const n = installed.filter((r) => r.serverId === s.id && r.status === "INSTALLED").length;
                      return (
                        <li key={s.id}>
                          <Link href={`/dashboard/servers/${s.id}?tab=mods`} className="flex items-center gap-2.5 rounded-xl border border-[rgba(150,175,255,.16)] px-3 py-2.5 hover:border-[rgba(150,140,255,.5)]" prefetch={false}>
                            <span className="nxl-srv-dot" data-status={s.status} aria-hidden />
                            <span className="min-w-0 flex-1 truncate text-[13px] font-bold text-white">{s.name}</span>
                            <span className="text-[11.5px] text-[#93aede]">{n} mod{n === 1 ? "" : "s"}</span>
                          </Link>
                        </li>
                      );
                    })}
                  </ul>
                  <p className="mt-3 text-[12px] leading-[1.5] text-[#93aede]">Tap <b className="text-white">Add</b> on any card below to install it on one of these.</p>
                </>
              ) : deploy ? (
                <>
                  <p className="flex items-center gap-2 text-[13px] font-extrabold text-white"><span className="nxl-srv-dot" data-status="RUNNING" aria-hidden /> {label} server</p>
                  <p className="mt-3 text-[#93aede]">From <b className="text-[28px] font-extrabold tracking-[-0.02em] text-white">{formatPriceCents(deploy.plan.priceCents)}</b>/month</p>
                  <ul className="mt-3 flex flex-col gap-1.5 text-[12.5px] text-[#cbdcff]">
                    <li className="flex items-center gap-2"><Icon name="bolt" size={12} /> One-tap mods from NxLabs</li>
                    <li className="flex items-center gap-2"><Icon name="shieldcheck" size={12} /> DDoS protection included</li>
                    <li className="flex items-center gap-2"><Icon name="refresh" size={12} /> Daily restore points</li>
                  </ul>
                  <Link href={deploy.href} className="nxl-gobtn mt-4 w-full justify-center">Deploy a {label} server <span aria-hidden>→</span></Link>
                </>
              ) : (
                <>
                  <p className="text-[13px] font-extrabold text-white">Download and upload</p>
                  <p className="mt-2 text-[12.5px] leading-[1.5] text-[#93aede]">
                    Every mod here links to its real source. Download it there and upload it to your server in Files.
                  </p>
                </>
              )}
            </aside>
          </div>
        </header>

        <LabsTabs active={filtered ? "browse" : "discover"} installedCount={liveCount} />

        {!filtered && (
          <>
            {rail(`Featured ${label} mods`, "Start here", `The ${label} mods the NxLabs catalogue marks as featured.`, featured, `${base}#browse`, "featured")}
            {cats.length > 0 && (
              <section>
                <LabsHead eyebrow="Collections" title={`Browse ${label} by what you need`} />
                <LabsCategoryTiles cats={cats} hrefFor={(k) => `${base}?cat=${k}#browse`} />
              </section>
            )}
            {rail(`Most downloaded`, "Real downloads, real ranking", undefined, top, `${base}?sort=downloads#browse`, "top-downloaded")}
            {rail(`Recently updated`, "Straight from the source", undefined, recent, `${base}?sort=updated#browse`, "recently-updated")}
            {rail(`Top rated`, "Community favourites", "Ranked by downloads until a mod has enough customer ratings of its own.", rated, `${base}?sort=rating#browse`, "top-rated")}
          </>
        )}

        <section id="browse" className="scroll-mt-24">
          {!filtered && <LabsHead eyebrow="Everything" title={`All ${label} mods`} />}
          <LabsToolbar
            base={base}
            state={{ q: p.q, sort: p.sort, cat: p.cat, loader: p.loader, version: p.version, category: p.category }}
            sorts={LABS_SORTS}
            cats={cats.map((c) => ({ value: c.cat.key, label: c.cat.label, count: c.count }))}
            loaders={loaders.map((l) => ({ value: l.loader, label: loaderLabel(l.loader), count: l.count }))}
            versions={versions.map((v) => ({ value: v.version, label: v.version, count: v.count }))}
            sources={rawCats.map((c) => ({ value: c.category, label: c.category, count: c.count }))}
            total={result.total}
            placeholder={`Search ${label} mods`}
          />
          <LabsPending className="mt-4">
            {result.mods.length > 0 ? (
              <>
                <LabsGrid>{result.mods.map((m, i) => labsCard(m, { ...ctx, priority: filtered && i < 4 }))}</LabsGrid>
                <LabsPager page={result.page} totalPages={result.totalPages} total={result.total} perPage={result.perPage || PER_PAGE}
                           hrefFor={(n) => labsHref(base, p, { page: n })} />
              </>
            ) : (
              <LabsEmpty
                title={p.q ? `No ${label} mods match “${p.q}”` : `No ${label} mods match these filters`}
                body={`Try a broader search${p.cat ? `, another category than ${catLabel(p.cat)}` : ""}${p.version ? ", or any game version" : ""}.`}
                action={<>
                  <Link href={`${base}#browse`} className="btn-secondary">Clear filters</Link>
                  {p.q && <Link href={`/dashboard/nxlabs?q=${encodeURIComponent(p.q)}#browse`} className="btn-secondary">Search every game</Link>}
                </>}
              />
            )}
          </LabsPending>
        </section>
      </LabsNavProvider>
    </div>
  );
}

