            {rail(`Most downloaded`, "Real downloads, real ranking", undefined, top, `${base}?sort=downloads#browse`, "top-downloaded")}
            {rail(`Recently updated`, "Straight from the source", undefined, recent, `${base}?sort=updated#browse`, "recently-updated")}
            {rail(`Top rated`, "Community favourites", "Ranked by downloads until a mod has enough customer ratings of its own.", rated, `${base}?sort=rating#browse`, "top-rated")}
          </>
        )}

        <section id="browse" className="scroll-mt-24">
          {!filtered && <LabsHead eyebrow="Everything" title={`All ${label} mods`} />}
          <LabsToolbar
            base={base}
            state={{ q: p.q, sort: p.sort, cat: p.cat, loader: p.loader, version: p.version, category: p.category }}
            sorts={LABS_SORTS}
            cats={cats.map((c) => ({ value: c.cat.key, label: c.cat.label, count: c.count }))}
            loaders={loaders.map((l) => ({ value: l.loader, label: loaderLabel(l.loader), count: l.count }))}
            versions={versions.map((v) => ({ value: v.version, label: v.version, count: v.count }))}
            sources={rawCats.map((c) => ({ value: c.category, label: c.category, count: c.count }))}
            total={result.total}
            placeholder={`Search ${label} mods`}
          />
          <LabsPending className="mt-4">
            {result.mods.length > 0 ? (
              <>
                <LabsGrid>{result.mods.map((m, i) => labsCard(m, { ...ctx, priority: filtered && i < 4 }))}</LabsGrid>
                <LabsPager page={result.page} totalPages={result.totalPages} total={result.total} perPage={result.perPage || PER_PAGE}
                           hrefFor={(n) => labsHref(base, p, { page: n })} />
              </>
            ) : (
              <LabsEmpty
                title={p.q ? `No ${label} mods match “${p.q}”` : `No ${label} mods match these filters`}
                body={`Try a broader search${p.cat ? `, another category than ${catLabel(p.cat)}` : ""}${p.version ? ", or any game version" : ""}.`}
                action={<>
                  <Link href={`${base}#browse`} className="btn-secondary">Clear filters</Link>
                  {p.q && <Link href={`/dashboard/nxlabs?q=${encodeURIComponent(p.q)}#browse`} className="btn-secondary">Search every game</Link>}
                </>}
              />
            )}
          </LabsPending>
        </section>
      </LabsNavProvider>
    </div>
  );
}

