"use client";

import Link from "next/link";
import { useEffect, useState } from "react";

export function ModBackLink({
  gameFamilyHref,
  gameFamilyLabel,
  fallbackHref,
  fallbackLabel,
  className,
}: {
  gameFamilyHref: string;
  gameFamilyLabel: string;
  fallbackHref: string;
  fallbackLabel: string;
  className?: string;
}) {
  const [target, setTarget] = useState<{ href: string; label: string }>({ href: fallbackHref, label: fallbackLabel });

  useEffect(() => {
    try {
      const ref = document.referrer;
      if (!ref) return;
      const refUrl = new URL(ref);
      if (refUrl.origin !== window.location.origin) return;
      const refPath = refUrl.pathname.replace(/\/+$/, "");
      const gamePath = gameFamilyHref.replace(/\/+$/, "");
      if (refPath === gamePath) {
        setTarget({ href: gameFamilyHref, label: gameFamilyLabel });
      }
    } catch {
      // Malformed or unparsable referrer — keep the fallback target.
    }
  }, [gameFamilyHref, gameFamilyLabel]);

  return (
    <Link
      href={target.href}
      className={
        className ??
        "inline-flex items-center gap-1.5 text-sm font-medium text-brand-300 transition-colors hover:text-brand-200"
      }
    >
      <svg width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2.4" strokeLinecap="round" strokeLinejoin="round" aria-hidden>
        <path d="m15 18-6-6 6-6" />
      </svg>
      Back to {target.label}
    </Link>
  );
/**
 * Real creator credit for a mod (GameMod.authorName/authorAvatarUrl —
 * resolved from the source's own project/team/author data by
 * scripts/verify-gamemods.ts). No "Follow" button: there is no real follow
 * relationship behind one, and NxLabs's rule against fabricated interactions
 * means omitting it rather than wiring a button to nothing.
 */
export function AuthorBadge({ name, avatarUrl }: { name: string; avatarUrl: string | null }) {
  return (
    <div className="flex items-center gap-2 text-sm">
      <span className="flex h-7 w-7 shrink-0 items-center justify-center overflow-hidden rounded-full border border-white/10 bg-white/[0.06] text-xs font-semibold text-[var(--fg-muted)]">
        {avatarUrl ? (
          // eslint-disable-next-line @next/next/no-img-element
          <img src={avatarUrl} alt="" className="h-full w-full object-cover" />
        ) : (
          name.slice(0, 1).toUpperCase()
        )}
      </span>
      <span className="text-[var(--fg-muted)]">
        By <span className="font-medium text-[var(--fg)]">{name}</span>
      </span>
    </div>
  );
}

