import Link from "next/link";
import { notFound } from "next/navigation";
import { requireUser } from "@/lib/auth";
import { db } from "@/lib/db";
import { RatingsAndComments } from "@/components/mods/RatingsAndComments";
import { ModBackLink } from "@/components/mods/ModBackLink";
import { renderModBody, type ModBodySource } from "@/lib/mod-markdown";
import {
  getCatalogMod,
  relatedCatalogMods,
  recommendedPlanFor,
  resolveDownloadUrl,
  listModComments,
  getMyModRating,
  formatDownloads,
  formatBytes,
  formatPriceCents,
  composedDescriptionFor,
  SOURCE_LABEL,
} from "@/lib/mods-catalog";
import { CARD_ILL, ago, catOf, gameArt, loaderLabel } from "@/app/nxm/_data/mods-lib";
import { taxOf } from "@/app/nxm/_data/mods-taxonomy";
import { LabsImg } from "@/components/nx/labs/LabsImg";
import { LabsGrid } from "@/components/nx/labs/LabsCard";
import { LabsInstallPanel } from "@/components/nx/labs/LabsInstall";
import { LabsDownload } from "@/components/nx/labs/LabsDownload";
import { LabsHead, LabsTabs } from "@/components/nx/labs/LabsBits";
import { Icon } from "@/components/nx/Icon";
import { deployFor, installStateFor, installTargets, myInstalledMods, myModServers } from "../../_lib/labs";
import { labsCard } from "../../_lib/cards";
import "../../labs.css";

export const dynamic = "force-dynamic";

/**
 * Portal mod detail — same data as the public /mods/[family]/[slug] page
 * (lib/mods-catalog.ts), in the portal shell, with the signed-in pieces:
 * install onto one of YOUR servers (and what's already there), your rating.
 */
export default async function PortalModDetailPage({ params }: { params: Promise<{ family: string; slug: string }> }) {
  const { family, slug } = await params;
  const user = await requireUser();
  const mod = await getCatalogMod(family, slug);
  if (!mod) notFound();

  const [gamePlans, related, download, commentsPage, myRating, servers, deploy] = await Promise.all([
    db.gamePlan.findMany({ where: { gameFamily: mod.gameFamily, active: true }, orderBy: { priceCents: "asc" } }),
    relatedCatalogMods(mod, 4),
    resolveDownloadUrl(mod),
    listModComments(mod.id, { take: 10 }),
    getMyModRating(mod.id, user.id),
    myModServers(user.id),
    deployFor(mod.gameFamily, mod.impact),
  ]);
  const family_servers = servers.filter((s) => s.family === mod.gameFamily);
  const [state, installed] = await Promise.all([
    installStateFor(family_servers.map((s) => s.id), [mod.id, ...related.map((r) => r.id)]),
    myInstalledMods(servers.map((s) => s.id)),
  ]);
  const targets = installTargets(mod, servers);
  const installServers = targets.servers.map((s) => ({ ...s, installed: state[mod.id]?.find((r) => r.serverId === s.id)?.status ?? null }));
  const recommended = recommendedPlanFor(mod, gamePlans);

  const c = catOf(mod);
  const tax = taxOf(mod);
  const source = SOURCE_LABEL[mod.source] ?? mod.source;
  const downloads = formatDownloads(mod.downloads);
  const fileSize = formatBytes(mod.fileBytes);
  const updated = ago(mod.upstreamUpdatedAt);
  const heroArt = mod.galleryUrls[0] ?? gameArt(mod.gameFamily).hero;
  const longDescription = mod.longDescription ? renderModBody(mod.longDescription, mod.source as ModBodySource, 6000) : null;
  const description = mod.description || composedDescriptionFor(mod);
  const versions = mod.gameVersions.slice(-6).reverse();
  const liveCount = installed.filter((r) => r.status === "INSTALLED" || r.status === "INSTALLING").length;
  const gameHref = `/dashboard/nxlabs/games/${encodeURIComponent(mod.gameFamily)}`;

  const facts = [
    downloads && { k: "Downloads", v: downloads },
    updated && { k: "Last updated", v: updated },
    mod.license && { k: "License", v: mod.license },
    mod.loaders.length > 0 && { k: mod.loaders.length > 1 ? "Loaders" : "Loader", v: mod.loaders.slice(0, 3).map(loaderLabel).join(", ") },
    versions[0] && { k: "Newest version", v: versions[0] },
    fileSize && { k: "File size", v: fileSize },
  ].filter(Boolean) as { k: string; v: string }[];

  const downloadCtl = download ? (
    <LabsDownload modId={mod.id} url={download.url} label={download.direct ? "Download file" : `View on ${source}`} className="btn-secondary inline-flex items-center justify-center gap-2" />
  ) : null;

  return (
    <div className="nxl-root mx-auto flex w-full max-w-[1520px] flex-col gap-6" style={{ "--c1": c.c1, "--c2": c.c2 } as React.CSSProperties}>
      {/* ── hero ─────────────────────────────────────────────────────── */}
      <header className="nxl-hero is-game nx-dark-island nxl-dhero">
        <div className="nxl-hero-bg" aria-hidden>
          <LabsImg src={heroArt} eager className={mod.galleryUrls[0] ? "scale-110 blur-[6px]" : ""} />
        </div>
        <div className="flex flex-col gap-5">
          <div className="flex flex-wrap items-center gap-x-4 gap-y-2">
            <ModBackLink
              gameFamilyHref={gameHref}
              gameFamilyLabel={mod.gameFamilyLabel}
              fallbackHref="/dashboard/nxlabs"
              fallbackLabel="NxLabs"
              className="inline-flex items-center gap-1.5 text-[13px] font-semibold text-[#c9b8ff] hover:text-white"
            />
            <nav aria-label="Breadcrumb" className="flex min-w-0 items-center gap-2 text-[13px] font-semibold text-[#93aede]">
              <Link href="/dashboard/nxlabs" className="hover:text-white" prefetch={false}>NxLabs</Link>
              <span aria-hidden>/</span>
              <Link href={gameHref} className="hover:text-white" prefetch={false}>{mod.gameFamilyLabel}</Link>
              <span aria-hidden>/</span>
              <span className="truncate text-white">{mod.name}</span>
            </nav>
          </div>

          <div className="flex items-start gap-4 sm:gap-5">
            <span className="nxl-dicon" aria-hidden>
              {mod.name.slice(0, 1).toUpperCase()}
              <LabsImg src={mod.iconUrl} eager />
            </span>
            <div className="flex min-w-0 flex-col gap-2">
              <div className="flex flex-wrap gap-1.5">
                {mod.verified && <span className="nxl-pill is-ok">✓ Verified</span>}
                <span className="nxl-pill">{c.label}</span>
                {mod.featured && <span className="nxl-pill">Featured</span>}
                {mod.paid && <span className="nxl-pill">Paid</span>}
              </div>
              <h1 className="break-words text-[28px] font-extrabold leading-[1.04] tracking-[-0.035em] sm:text-[44px]">{mod.name}</h1>
              <p className="text-[13.5px] text-[#b9c8ea]">
                {mod.authorName ? <>by <b className="text-white">{mod.authorName}</b> · </> : null}for {mod.gameFamilyLabel} · from {source}
              </p>
            </div>
          </div>
          <p className="max-w-[75ch] text-[14.5px] leading-[1.55] text-[#cbdcff]">{description}</p>

          {facts.length > 0 && (
            <dl className="nxl-facts">
              {facts.map((f) => <div key={f.k} className="nxl-fact"><b className="num">{f.v}</b><span>{f.k}</span></div>)}
            </dl>
          )}

          <div className="flex flex-wrap gap-2.5">
            <a href="#install" className="nxl-gobtn">
              <Icon name="plus" size={13} tone="inherit" />
              {installServers.some((s) => s.installed === "INSTALLED") ? "On your server" : "Add to my server"}
            </a>
            {download && (
              <LabsDownload modId={mod.id} url={download.url} label={download.direct ? "Download file" : `View on ${source}`} className="nxl-ghost" />
            )}
          </div>
        </div>
      </header>

      <LabsTabs active="browse" installedCount={liveCount} />

      <div className="grid gap-6 lg:grid-cols-[minmax(0,1fr)_380px]">
        <div className="flex min-w-0 flex-col gap-6">
          {mod.galleryUrls.length > 0 && (
            <section className="nxl-panel">
              <div className="mb-3 flex items-center justify-between gap-3"><h2 className="nxl-ptitle">Screenshots</h2><span className="nxl-tag">From {source}</span></div>
              <div className="nxl-gallery">
                {mod.galleryUrls.slice(0, 10).map((u, i) => (
                  <a key={u + i} href={u} target="_blank" rel="noopener noreferrer nofollow ugc" className="nxl-shot" aria-label={`Screenshot ${i + 1} of ${mod.name}`}>
                    <LabsImg src={u} alt="" />
                  </a>
                ))}
              </div>
            </section>
          )}

          <section className="nxl-panel">
            <div className="mb-2 flex items-center justify-between gap-3"><h2 className="nxl-ptitle">About {mod.name}</h2><span className="nxl-tag">From {source}</span></div>
            {longDescription?.html ? (
              <>
                {/* lib/mod-markdown.ts sanitises third-party bodies — same renderer as the public page. */}
                <div className="nxl-prose" dangerouslySetInnerHTML={{ __html: longDescription.html }} />
                {longDescription.truncated && mod.url && (
                  <a href={mod.url} target="_blank" rel="noopener noreferrer nofollow ugc" className="nxl-more mt-3">
                    Read the full description on {source} <span aria-hidden>→</span>
                  </a>
                )}
              </>
            ) : (
              <p className="nxl-prose">{description}</p>
            )}
          </section>

          <section className="nxl-panel">
            <div className="mb-3 flex items-center justify-between gap-3"><h2 className="nxl-ptitle">Highlights</h2><span className="nxl-tag">From source data</span></div>
            <div className="nxl-hl">
              <div>
                <p className="text-[14px] font-extrabold text-white">Game versions</p>
                <p className="mt-1 text-[12.5px] leading-[1.5] text-tx-mute">
                  {mod.gameVersions.length > 0
                    ? `Supports ${mod.gameVersions.length} ${mod.gameFamilyLabel} version${mod.gameVersions.length === 1 ? "" : "s"}: ${versions.join(", ")}${mod.gameVersions.length > versions.length ? "…" : ""}`
                    : `${source} doesn't publish a version list for this one.`}
                </p>
              </div>
              <div>
                <p className="text-[14px] font-extrabold text-white">Loaders</p>
                <p className="mt-1 text-[12.5px] leading-[1.5] text-tx-mute">
                  {mod.loaders.length > 0 ? `Runs on ${mod.loaders.map(loaderLabel).join(", ")}.` : "No specific loader listed."}
                  {mod.appliesToVariant && ` Needs the ${mod.appliesToVariant} server type.`}
                </p>
              </div>
              <div>
                <p className="text-[14px] font-extrabold text-white">Footprint</p>
                <p className="mt-1 text-[12.5px] leading-[1.5] text-tx-mute">
                  {fileSize ? `A ${fileSize} download, ` : ""}rated a {mod.impact} load on a server.{mod.impactNote ? ` ${mod.impactNote}` : ""}
                  {mod.serverSide && ` Server-side: ${mod.serverSide}.`}
                </p>
              </div>
            </div>
          </section>

          <section className="nxl-panel">
            <div className="mb-3 flex items-center justify-between gap-3"><h2 className="nxl-ptitle">What kind of mod it is</h2><span className="nxl-tag">From the catalogue</span></div>
            <div className="flex items-center gap-4">
              <span className="relative block h-[64px] w-[104px] flex-none overflow-hidden rounded-xl" style={{ background: `linear-gradient(135deg, ${c.c1}, ${c.c2})` }} aria-hidden>
                <svg viewBox="0 0 200 120" preserveAspectRatio="xMidYMid slice" className="absolute inset-0 h-full w-full" dangerouslySetInnerHTML={{ __html: CARD_ILL[c.card] ?? CARD_ILL.core }} />
              </span>
              <div className="min-w-0">
                <p className="text-[10.5px] font-bold uppercase tracking-[0.1em] text-tx-faint">Listed on {source} as “{mod.category}”</p>
                <p className="text-[15px] font-extrabold text-white">{tax ? tax.label : mod.category}</p>
                <p className="text-[12.5px] text-tx-mute">{tax ? tax.desc : "Its source category doesn't say more about what it does, so NxLabs lists it under Other."}</p>
              </div>
            </div>
          </section>

          <RatingsAndComments
            modId={mod.id}
            avgRating={mod.avgRating}
            ratingCount={mod.ratingCount}
            initialComments={commentsPage.comments}
            initialCursor={commentsPage.nextCursor}
            myRating={myRating}
            isLoggedIn
            isAdmin={user.role === "ADMIN"}
            loginHref="/login"
          />
        </div>

        <aside className="flex min-w-0 flex-col gap-6">
          <div className="nxl-sticky flex flex-col gap-6">
            <section id="install" className="nxl-panel nxl-panel-glow scroll-mt-28">
              <div className="mb-3 flex items-center gap-3">
                <span className="nxl-dicon !h-11 !w-11 !rounded-xl !text-lg" aria-hidden>
                  {mod.name.slice(0, 1).toUpperCase()}
                  <LabsImg src={mod.iconUrl} />
                </span>
                <div className="min-w-0">
                  <h2 className="nxl-ptitle truncate">Add {mod.name} to a server</h2>
                  <p className="text-[12px] text-tx-faint">We install it, restart and switch it on.</p>
                </div>
              </div>
              <LabsInstallPanel
                modId={mod.id}
                modName={mod.name}
                gameLabel={mod.gameFamilyLabel}
                servers={installServers}
                supported={targets.supported}
                unsupportedReason={targets.unsupportedReason}
                deployHref={deploy?.href ?? null}
                downloadSlot={downloadCtl}
              />
              {family_servers.length > installServers.length && (
                <p className="mt-3 text-[12px] text-tx-faint">
                  {family_servers.length - installServers.length} of your {mod.gameFamilyLabel} servers can&apos;t take it
                  {mod.appliesToVariant ? ` — it needs the ${mod.appliesToVariant} server type` : ""}.
                </p>
              )}
              {installServers.length > 0 && deploy && (
                <Link href={deploy.href} className="nxl-more mt-3" prefetch={false}>Deploy another server <span aria-hidden>→</span></Link>
              )}
              {!mod.upstreamOk && (
                <p className="mt-3 rounded-lg border border-amber-500/30 bg-amber-500/10 px-3 py-2 text-xs text-amber-300">
                  {mod.upstreamNote || "This mod is no longer supported by its source."}
                </p>
              )}
              {!download && <p className="mt-3 text-[12px] text-tx-faint">No download link is available for this entry right now.</p>}
            </section>

            <section className="nxl-panel">
              <h2 className="mb-3 text-[11px] font-extrabold uppercase tracking-[0.14em] text-tx-faint">Details</h2>
              <dl className="nxl-dl">
                <div><dt>Game</dt><dd>{mod.gameFamilyLabel}</dd></div>
                <div><dt>Category</dt><dd>{tax ? tax.label : mod.category}</dd></div>
                <div><dt>Source</dt><dd>{mod.url ? <a href={mod.url} target="_blank" rel="noopener noreferrer nofollow ugc" className="underline-offset-2 hover:underline">{source}</a> : source}</dd></div>
                {mod.license && <div><dt>License</dt><dd>{mod.license}</dd></div>}
                {downloads && <div><dt>Downloads</dt><dd className="num">{downloads}</dd></div>}
                {fileSize && <div><dt>File size</dt><dd>{fileSize}</dd></div>}
                {versions.length > 0 && <div><dt>Game versions</dt><dd>{versions.join(", ")}</dd></div>}
                {mod.loaders.length > 0 && <div><dt>Loaders</dt><dd>{mod.loaders.map(loaderLabel).join(", ")}</dd></div>}
                {mod.appliesToVariant && <div><dt>Requires</dt><dd>{mod.appliesToVariant} server type</dd></div>}
                {mod.serverSide && <div><dt>Server support</dt><dd>{mod.serverSide}</dd></div>}
                {mod.dependencyCount > 0 && <div><dt>Dependencies</dt><dd>{mod.dependencyCount}</dd></div>}
                <div><dt>Verified</dt><dd>{mod.verified ? `Yes — checked ${mod.verifiedAt?.toISOString().slice(0, 10)}` : "Not yet verified"}</dd></div>
              </dl>
            </section>

            <section className="nxl-panel">
              <h2 className="mb-3 text-[11px] font-extrabold uppercase tracking-[0.14em] text-tx-faint">Recommended server</h2>
              {recommended ? (
                <div className="flex items-center gap-3 rounded-xl border border-[var(--color-rim)] px-4 py-3">
                  <span className="grid h-10 w-10 flex-none place-items-center rounded-lg bg-[rgba(140,58,233,.15)]"><Icon name="server" size={15} /></span>
                  <span className="min-w-0">
                    <span className="block truncate text-[13.5px] font-bold text-white">{recommended.planName}</span>
                    <span className="block text-[12px] text-tx-faint">
                      {(recommended.ramMB / 1024).toFixed(recommended.ramMB % 1024 ? 1 : 0)} GB RAM or higher · {formatPriceCents(recommended.priceCents)}/mo
                    </span>
                  </span>
                </div>
              ) : (
                <p className="text-[13px] text-tx-mute">{mod.impactNote || "This is a light install and should run fine on any active plan for this game."}</p>
              )}
              {deploy && installServers.length === 0 && (
                <Link href={deploy.href} className="btn-primary mt-3 flex items-center justify-center gap-2">Deploy {deploy.plan.planName}</Link>
              )}
            </section>
          </div>
        </aside>
      </div>

      {related.length > 0 && (
        <section className="mt-2">
          <LabsHead eyebrow="Keep exploring" title={`More for ${mod.gameFamilyLabel}`} href={gameHref} hrefLabel={`All ${mod.gameFamilyLabel} mods`} />
          <LabsGrid>{related.map((r) => labsCard(r, { servers: family_servers, state }))}</LabsGrid>
        </section>
      )}
    </div>
  );
}

