import Link from "next/link";
import { requireUser } from "@/lib/auth";
import { families as listFamilies, catOf, gameArt } from "@/app/nxm/_data/mods-lib";
import { LabsTabs, LabsEmpty, LabsHead } from "@/components/nx/labs/LabsBits";
import { LabsImg } from "@/components/nx/labs/LabsImg";
import { Icon } from "@/components/nx/Icon";
import { myInstalledMods, myModServers } from "../_lib/labs";
import { modHref } from "../_lib/cards";
import "../labs.css";

export const dynamic = "force-dynamic";

const STATUS: Record<string, { label: string; cls: string }> = {
  INSTALLED: { label: "Installed", cls: "is-ok" },
  INSTALLING: { label: "Installing…", cls: "" },
  REMOVING: { label: "Removing…", cls: "" },
  FAILED: { label: "Install failed", cls: "is-bad" },
};

/**
 * "On my servers" — every NX Labs mod on every game server this customer
 * owns, grouped by server, with its real ServerMod state (installed /
 * installing / failed + the worker's error). Read-only on purpose: install,
 * update and remove stay in each server's Mods tab (one place that owns those
 * mechanics), which every row links straight into.
 */
export default async function NxLabsInstalledPage() {
  const user = await requireUser();
  const [servers, fams] = await Promise.all([myModServers(user.id), listFamilies()]);
  const rows = await myInstalledMods(servers.map((s) => s.id));
  const label = (f: string) => fams.find((x) => x.family === f)?.label ?? f;
  const live = rows.filter((r) => r.status === "INSTALLED" || r.status === "INSTALLING").length;
  const failed = rows.filter((r) => r.status === "FAILED").length;

  return (
    <div className="nxl-root mx-auto flex w-full max-w-[1520px] flex-col gap-6">
      <header className="nxl-hero nx-dark-island px-5 py-7 sm:px-9">
        <div className="nxl-hero-bg" aria-hidden>
          {/* eslint-disable-next-line @next/next/no-img-element -- static hero art */}
          <img src="/nxlabs/hero-collage.webp" alt="" decoding="async" />
        </div>
        <p className="nxl-eyebrow">NxLabs</p>
        <h1 className="text-[28px] font-extrabold leading-[1.05] tracking-[-0.035em] sm:text-[36px]">On my servers</h1>
        <p className="mt-2 max-w-[62ch] text-[13.5px] text-[#b9c8ea]">
          {rows.length
            ? `${live} mod${live === 1 ? "" : "s"} across ${new Set(rows.map((r) => r.serverId)).size} server${new Set(rows.map((r) => r.serverId)).size === 1 ? "" : "s"}${failed ? ` · ${failed} need${failed === 1 ? "s" : ""} attention` : ""}. Updates and removal live in each server's Mods tab.`
            : "Everything you install from NxLabs shows up here, server by server."}
        </p>
      </header>

      <LabsTabs active="installed" installedCount={live} />

      {servers.length === 0 ? (
        <LabsEmpty
          title="No game servers yet"
          body="NxLabs installs mods onto your own game servers. Deploy one and anything you add from the catalogue appears here."
          action={<>
            <Link href="/dashboard/deploy" className="btn-primary">Deploy a game server</Link>
            <Link href="/dashboard/nxlabs" className="btn-secondary">Browse NxLabs</Link>
          </>}
        />
      ) : rows.length === 0 ? (
        <LabsEmpty
          title="Nothing installed yet"
          body="Find a mod for one of your servers and tap Add — it's installed, the server restarts, and it shows up here."
          action={<Link href="/dashboard/nxlabs" className="btn-primary">Browse NxLabs</Link>}
        />
      ) : (
        <div className="flex flex-col gap-6">
          {servers.map((s) => {
            const mine = rows.filter((r) => r.serverId === s.id);
            if (!mine.length) return null;
            const art = gameArt(s.family).poster;
            return (
              <section key={s.id} className="nxl-panel">
                <div className="mb-4 flex flex-wrap items-center gap-3">
                  <span className="relative grid h-12 w-10 flex-none place-items-center overflow-hidden rounded-lg bg-[linear-gradient(150deg,#1b2f6b,#3a1f78)] text-[12px] font-black text-white/60" aria-hidden>
                    {label(s.family).slice(0, 2).toUpperCase()}
                    <LabsImg src={art} className="absolute inset-0 h-full w-full object-cover" />
                  </span>
                  <div className="min-w-0 flex-1">
                    <h2 className="flex items-center gap-2 truncate text-[16px] font-extrabold text-white">
                      <span className="nxl-srv-dot" data-status={s.status} aria-hidden /> {s.name}
                    </h2>
                    <p className="text-[12px] text-tx-faint">{label(s.family)} · {mine.length} mod{mine.length === 1 ? "" : "s"}</p>
                  </div>
                  <Link href={`/dashboard/servers/${s.id}?tab=mods`} className="btn-secondary inline-flex items-center gap-1.5" prefetch={false}>
                    <Icon name="gear" size={12} tone="inherit" /> Manage in Mods tab
                  </Link>
                  <Link href={`/dashboard/nxlabs/games/${s.family}`} className="nxl-more" prefetch={false}>Find more <span aria-hidden>→</span></Link>
                </div>
                <ul className="grid gap-2.5 md:grid-cols-2">
                  {mine.map((r) => {
                    const st = STATUS[r.status] ?? { label: r.status, cls: "" };
                    const c = catOf(r.mod);
                    const listed = r.mod.active && r.mod.upstreamOk;
                    const inner = (
                      <>
                        <span className="nxl-card-mono !static !h-10 !w-10 !border-0 !text-[15px]" style={{ "--c1": c.c1, "--c2": c.c2 } as React.CSSProperties} aria-hidden>
                          <span>{r.mod.name.slice(0, 1).toUpperCase()}</span>
                          <LabsImg src={r.mod.iconUrl} className="nxl-card-icon" />
                        </span>
                        <span className="min-w-0 flex-1">
                          <span className="block truncate text-[13.5px] font-bold text-white">{r.mod.name}</span>
                          <span className="block truncate text-[11.5px] text-tx-faint">
                            {c.label}{r.version ? ` · v${r.version}` : ""}{!listed ? " · no longer listed" : ""}
                          </span>
                          {r.status === "FAILED" && r.error && <span className="mt-0.5 block text-[11.5px] text-red-400">{r.error}</span>}
                        </span>
                        <span className={"nxl-badge " + st.cls}>{st.label}</span>
                      </>
                    );
                    return (
                      <li key={r.id}>
                        {listed ? (
                          <Link href={modHref(r.mod)} className="flex items-center gap-3 rounded-xl border border-[var(--color-rim)] px-3 py-2.5 transition-colors hover:border-[var(--color-rim-hi)]" prefetch={false}>{inner}</Link>
                        ) : (
                          <div className="flex items-center gap-3 rounded-xl border border-[var(--color-rim)] px-3 py-2.5">{inner}</div>
                        )}
                      </li>
                    );
                  })}
                </ul>
              </section>
            );
          })}
          <div>
            <LabsHead title="Looking for more?" sub="Browse the catalogue for the games you run." />
            <div className="flex flex-wrap gap-2">
              {Array.from(new Set(servers.map((s) => s.family))).map((f) => (
                <Link key={f} href={`/dashboard/nxlabs/games/${f}`} className="nxl-chip" prefetch={false}>{label(f)} mods</Link>
              ))}
            </div>
          </div>
        </div>
      )}
    </div>
  );
}

