// Usage: node shots.cjs <outdir> [pages...]   (dev server must be on :3116)
const { chromium } = require('/opt/nxeon/node_modules/playwright');
const { SignJWT } = require('/opt/nxeon/node_modules/jose');
const fs = require('fs');
const env = Object.fromEntries(fs.readFileSync('/opt/nxeon-wt-nxlabs/.env', 'utf8').split('\n').filter(Boolean).map(l => [l.slice(0, l.indexOf('=')), l.slice(l.indexOf('=') + 1)]));
const out = process.argv[2] || 'shots';
fs.mkdirSync(out, { recursive: true });
const BASE = 'http://localhost:3116';
const PAGES = (process.env.PAGES || '').split(',').filter(Boolean);
const USER = process.env.USERID;
const MODES = (process.env.MODES || 'desktop-dark,desktop-light,mobile-dark,mobile-light').split(',');
const FULL = process.env.FULL === '1';

(async () => {
  const token = await new SignJWT({ sub: USER, sv: 0, typ: 'session' }).setProtectedHeader({ alg: 'HS256' }).setIssuedAt().setExpirationTime('1d').sign(new TextEncoder().encode(env.AUTH_SECRET));
  const b = await chromium.launch();
  const errors = [];
  for (const mode of MODES) {
    const [dev, theme] = mode.split('-');
    const ctx = await b.newContext({
      viewport: dev === 'mobile' ? { width: 390, height: 844 } : { width: 1440, height: 900 },
      deviceScaleFactor: 1, isMobile: dev === 'mobile', hasTouch: dev === 'mobile',
      reducedMotion: process.env.RM === '1' ? 'reduce' : 'no-preference',
    });
    await ctx.addCookies([{ name: env.NXEON_COOKIE_NAME, value: token, domain: 'localhost', path: '/' }]);
    await ctx.addInitScript((t) => { try { localStorage.setItem('nx-theme', t); } catch (e) {} }, theme);
    const p = await ctx.newPage();
    p.on('console', (m) => { if (m.type() === 'error') errors.push(`[${mode}] ${p.url()} :: ${m.text()}`); });
    p.on('pageerror', (e) => errors.push(`[${mode}] ${p.url()} :: PAGEERROR ${e.message}`));
    for (const path of PAGES) {
      const name = path.replace(/[^a-z0-9]+/gi, '_').replace(/^_|_$/g, '') || 'root';
      const t0 = Date.now();
      const r = await p.goto(BASE + path, { waitUntil: 'networkidle', timeout: 180000 }).catch((e) => { errors.push(`[${mode}] ${path} GOTO ${e.message}`); return null; });
      const ms = Date.now() - t0;
      await p.waitForTimeout(800);
      const fname = `${out}/${name}__${mode}.png`;
      await p.screenshot({ path: fname, fullPage: FULL });
      const ov = await p.evaluate(() => document.documentElement.scrollWidth - window.innerWidth);
      console.log(mode, path, r && r.status(), `${ms}ms`, ov > 0 ? `HORIZONTAL-OVERFLOW ${ov}px` : '');
    }
    await ctx.close();
  }
  await b.close();
  fs.writeFileSync(`${out}/console-errors.txt`, errors.join('\n'));
  console.log('console errors:', errors.length);
  for (const e of errors.slice(0, 30)) console.log(e);
})();

